#define HOME_WIDGET_DATEWX     6
#define HOME_WIDGET_STATS      7
#define HOME_WIDGET_MUSIC      8
#define HOME_WIDGET_RADIO      9
#define HOME_WIDGET_RECENT     10
#define HOME_WIDGET_BATTERY    11
#define HOME_WIDGET_CALENDAR   12

// App Focused owns a separate, phone-style two-cell widget. Switching Home
// layouts never leaks either layout's widget choices into the other one.
#define APP_WIDGET_NONE     0
#define APP_WIDGET_WEATHER  1
#define APP_WIDGET_CLOCK    2
#define APP_WIDGET_BATTERY  3
#define APP_WIDGET_CALENDAR 4
#define APP_WIDGET_COUNT    5
const char *app_widget_names[APP_WIDGET_COUNT] = {
    "None", "Weather", "Clock", "Battery Health", "Calendar"
};
int app_widget_kind = APP_WIDGET_NONE;
int app_widget_slot = 0;             // physical 4x2 grid cell; widget spans two columns
int app_widget_picker = 0;
int app_widget_picker_sel = 0;
int app_widget_moving = 0;
int app_widget_slot_backup = 0;
time_t calendar_selected_date = 0;  // always reset to today on Calendar entry/exit
#define CALENDAR_REMINDER_MAX 128
typedef struct {
    int ymd;
    int minute_of_day;  // -1 = all day; otherwise 0..1439
    char text[160];
} CalendarReminder;
CalendarReminder calendar_reminders[CALENDAR_REMINDER_MAX];
int calendar_reminder_count = 0;
int calendar_reminder_last_shown = 0;
int calendar_reminder_popup = 0;
int calendar_reminder_delete_confirm = 0;
int calendar_reminder_time_picker = 0;
int calendar_reminder_time_choice = 0; // 0 = all day, 1 = specific time
int calendar_reminder_edit_minutes = 9 * 60;
char calendar_reminder_pending_text[160] = "";

static int calendar_ymd_from_tm(const struct tm *d) {
    return d ? (d->tm_year + 1900) * 10000 + (d->tm_mon + 1) * 100 + d->tm_mday : 0;
}

static void calendar_set_today(void) {
    time_t now = time(NULL); struct tm d = *localtime(&now);
    d.tm_hour = 12; d.tm_min = 0; d.tm_sec = 0;
    calendar_selected_date = mktime(&d);
    calendar_reminder_delete_confirm = 0;
    calendar_reminder_time_picker = 0;
    calendar_reminder_pending_text[0] = '\0';
}

static struct tm calendar_selected_tm(void) {
    if (!calendar_selected_date) calendar_set_today();
    return *localtime(&calendar_selected_date);
}

static int calendar_reminder_find(int ymd) {
    for (int i = 0; i < calendar_reminder_count; i++)
        if (calendar_reminders[i].ymd == ymd) return i;
    return -1;
}

static void calendar_reminders_path(char *out, size_t cap) {
    snprintf(out, cap, "%s/calendar-reminders.tsv", sn_data_root());
}

static void calendar_reminders_save(void) {
    char path[640], tmp[680]; calendar_reminders_path(path, sizeof path);
    snprintf(tmp, sizeof tmp, "%s.tmp", path);
    FILE *f = fopen(tmp, "w"); if (!f) return;
    fprintf(f, "last_shown\t%d\n", calendar_reminder_last_shown);
    for (int i = 0; i < calendar_reminder_count; i++) {
        char clean[160]; snprintf(clean, sizeof clean, "%s", calendar_reminders[i].text);
        for (char *p = clean; *p; p++) if (*p == '\t' || *p == '\n' || *p == '\r') *p = ' ';
        fprintf(f, "%d\t%d\t%s\n", calendar_reminders[i].ymd,
                calendar_reminders[i].minute_of_day, clean);
    }
    fclose(f); rename(tmp, path);
}

static void calendar_reminders_load(void) {
    calendar_reminder_count = 0; calendar_reminder_last_shown = 0;
    char path[640]; calendar_reminders_path(path, sizeof path);
    FILE *f = fopen(path, "r"); if (!f) return;
    char line[420];
    while (fgets(line, sizeof line, f)) {
        char *tab = strchr(line, '\t'); if (!tab) continue;
        *tab++ = '\0'; char *nl = strpbrk(tab, "\r\n"); if (nl) *nl = '\0';
        if (strcmp(line, "last_shown") == 0) { calendar_reminder_last_shown = atoi(tab); continue; }
        int ymd = atoi(line), minute = -1;
        char *text = tab;
        char *second_tab = strchr(tab, '\t');
        if (second_tab) {
            *second_tab++ = '\0';
            minute = atoi(tab);
            if (minute < -1 || minute > 1439) minute = -1;
            text = second_tab;
        }
        if (ymd > 0 && text[0] && calendar_reminder_count < CALENDAR_REMINDER_MAX) {
            calendar_reminders[calendar_reminder_count].ymd = ymd;
            calendar_reminders[calendar_reminder_count].minute_of_day = minute;
            snprintf(calendar_reminders[calendar_reminder_count].text,
                     sizeof calendar_reminders[calendar_reminder_count].text, "%.159s", text);
            calendar_reminder_count++;
        }
    }
    fclose(f);
}

static void calendar_reminder_set(int ymd, const char *text, int minute_of_day) {
    if (ymd <= 0 || !text || !text[0]) return;
    if (minute_of_day < -1 || minute_of_day > 1439) minute_of_day = -1;
    int i = calendar_reminder_find(ymd);
    if (i < 0) {
        if (calendar_reminder_count >= CALENDAR_REMINDER_MAX) return;
        i = calendar_reminder_count++;
        calendar_reminders[i].ymd = ymd;
    }
    calendar_reminders[i].minute_of_day = minute_of_day;
    snprintf(calendar_reminders[i].text, sizeof calendar_reminders[i].text, "%.159s", text);
    // Editing today's reminder creates a new due event, even if an earlier
    // version of that reminder was already dismissed today.
    if (ymd == calendar_reminder_last_shown) calendar_reminder_last_shown = 0;
    calendar_reminders_save();
}

static void calendar_format_time(int minutes, char *out, size_t cap) {
    if (!out || cap == 0) return;
    if (minutes < 0) { snprintf(out, cap, "All Day"); return; }
    int hour24 = (minutes / 60) % 24, minute = minutes % 60;
    int hour12 = hour24 % 12; if (!hour12) hour12 = 12;
    snprintf(out, cap, "%d:%02d %s", hour12, minute, hour24 >= 12 ? "PM" : "AM");
}

static void calendar_reminder_remove(int ymd) {
    int i = calendar_reminder_find(ymd); if (i < 0) return;
    memmove(&calendar_reminders[i], &calendar_reminders[i + 1],
            (size_t)(calendar_reminder_count - i - 1) * sizeof calendar_reminders[0]);
    calendar_reminder_count--; calendar_reminders_save();
}

static void calendar_move_days(int days) {
    struct tm d = calendar_selected_tm(); d.tm_mday += days; d.tm_hour = 12;
    calendar_selected_date = mktime(&d);
}

static void calendar_move_month(int months) {
    struct tm d = calendar_selected_tm(); int wanted = d.tm_mday;
    d.tm_mday = 1; d.tm_mon += months; d.tm_hour = 12; mktime(&d);
    struct tm last = d; last.tm_mon += 1; last.tm_mday = 0; mktime(&last);
    d.tm_mday = wanted > last.tm_mday ? last.tm_mday : wanted;
    calendar_selected_date = mktime(&d);
}

static int calendar_widget_active(void) {
    if (home_view_idx == HOME_VIEW_APPS) return app_widget_kind == APP_WIDGET_CALENDAR;
    return home_widget_idx == HOME_WIDGET_CALENDAR || home_widget2_idx == HOME_WIDGET_CALENDAR;
}

static void calendar_reminder_check_today(void) {
    if (calendar_reminder_popup || !calendar_widget_active()) return;
    time_t now = time(NULL); struct tm today = *localtime(&now);
    int ymd = calendar_ymd_from_tm(&today);
    int i = calendar_reminder_find(ymd);
    if (ymd != calendar_reminder_last_shown && i >= 0) {
        int current_minute = today.tm_hour * 60 + today.tm_min;
        if (calendar_reminders[i].minute_of_day < 0 ||
            current_minute >= calendar_reminders[i].minute_of_day)
            calendar_reminder_popup = 1;
    }
}

static void calendar_reminder_dismiss(void) {
    time_t now = time(NULL); struct tm today = *localtime(&now);
    calendar_reminder_last_shown = calendar_ymd_from_tm(&today);
    calendar_reminder_popup = 0;
    calendar_reminders_save();
}

// The calculator keeps its working value while the app is open (and between
// quick trips Home), just like a pocket calculator. X clears and Y backspaces.
char calculator_display[40] = "0";
double calculator_accumulator = 0.0;
char calculator_pending_op = '\0';
int calculator_new_entry = 1;
int calculator_error = 0;
int calculator_selected = 0;

static void calculator_reset(void) {
    snprintf(calculator_display, sizeof calculator_display, "0");
    calculator_accumulator = 0.0;
    calculator_pending_op = '\0';
    calculator_new_entry = 1;
    calculator_error = 0;
}

static void calculator_set_value(double value) {
    if (!isfinite(value)) {
        snprintf(calculator_display, sizeof calculator_display, "Error");
        calculator_error = 1;
        calculator_new_entry = 1;
        return;
    }
    if (fabs(value) < 1e-12) value = 0.0;
    snprintf(calculator_display, sizeof calculator_display, "%.10g", value);
}

static int calculator_apply_pending(double rhs) {
    if (!calculator_pending_op) {
        calculator_accumulator = rhs;
        return 1;
    }
    switch (calculator_pending_op) {
        case '+': calculator_accumulator += rhs; break;
        case '-': calculator_accumulator -= rhs; break;
        case '*': calculator_accumulator *= rhs; break;
        case '/':
            if (fabs(rhs) < 1e-12) {
                snprintf(calculator_display, sizeof calculator_display, "Error");
                calculator_error = 1;
                calculator_pending_op = '\0';
                calculator_new_entry = 1;
                return 0;
            }
            calculator_accumulator /= rhs;
            break;
    }
    calculator_set_value(calculator_accumulator);
    return !calculator_error;
}

static void calculator_press(const char *key) {
    if (!key || !key[0]) return;
    if (calculator_error) calculator_reset();
    if ((key[0] >= '0' && key[0] <= '9') || key[0] == '.') {
        if (calculator_new_entry) {
            snprintf(calculator_display, sizeof calculator_display, key[0] == '.' ? "0." : "%c", key[0]);
            calculator_new_entry = 0;
        } else if (key[0] == '.') {
            if (!strchr(calculator_display, '.') && strlen(calculator_display) + 1 < sizeof calculator_display)
                strcat(calculator_display, ".");
        } else if (!(strcmp(calculator_display, "0") == 0 && key[0] == '0')) {
            size_t n = strlen(calculator_display);
            if (n + 1 < sizeof calculator_display) {
                if (strcmp(calculator_display, "0") == 0) calculator_display[0] = '\0';
                n = strlen(calculator_display);
                calculator_display[n] = key[0]; calculator_display[n + 1] = '\0';
            }
        }
        return;
    }
    double shown = strtod(calculator_display, NULL);
    if (key[0] == '=') {
        if (!calculator_new_entry || calculator_pending_op) calculator_apply_pending(shown);
        calculator_pending_op = '\0';
        calculator_new_entry = 1;
        return;
    }
    if (key[0] == '+' || key[0] == '-' || key[0] == '*' || key[0] == '/') {
        if (!calculator_new_entry || !calculator_pending_op) {
            if (!calculator_apply_pending(shown)) return;
        }
        calculator_pending_op = key[0];
        calculator_new_entry = 1;
    }
}

static void calculator_backspace(void) {
    if (calculator_error) { calculator_reset(); return; }
    if (calculator_new_entry) return;
    size_t n = strlen(calculator_display);
    if (n <= 1 || (n == 2 && calculator_display[0] == '-')) {
        snprintf(calculator_display, sizeof calculator_display, "0");
        calculator_new_entry = 1;
    } else calculator_display[n - 1] = '\0';
}

// A combined time/weather card is mutually exclusive with each of its
// component cards. This helper is shared by settings, boot repair and the
// live R1/R2 widget cycler so duplicate information can never occupy both.
static int home_widgets_conflict(int a, int b) {
    if (a == HOME_WIDGET_NONE || b == HOME_WIDGET_NONE) return 0;
    if (a == b) return 1;
    if (a == HOME_WIDGET_DATEWX &&
        (b == HOME_WIDGET_CLOCK || b == HOME_WIDGET_DATE || b == HOME_WIDGET_WEATHER)) return 1;
    if (b == HOME_WIDGET_DATEWX &&
        (a == HOME_WIDGET_CLOCK || a == HOME_WIDGET_DATE || a == HOME_WIDGET_WEATHER)) return 1;
    return 0;
}
static int home_widget_cycle(int cur, int other, int dir) {
    for (int n = 0; n < HOME_WIDGET_COUNT; n++) {
        cur = (cur + dir + HOME_WIDGET_COUNT) % HOME_WIDGET_COUNT;
        if (!home_widgets_conflict(cur, other)) return cur;
    }
    return HOME_WIDGET_NONE;
}

int home_recent_focus_slot = 0;  // 0=left navigation, 1=top widget, 2=bottom
int home_recent_widget_sel = 0;

// Weather is pulled by a detached curl to wttr.in into a tmp file; the render
// path just reads whatever's there. Never blocks the UI. Auto-refreshes every
// ~3h (every ~10min while we still have no reading), plus a manual refresh in
// Settings > Game.
#define WEATHER_TMP "/tmp/snapos-weather.txt"
#define WEATHER_PERIOD_MS   (3u * 60u * 60u * 1000u)   // normal cadence: 3 hours
#define WEATHER_RETRY_MS    (10u * 60u * 1000u)        // faster while we have nothing
char   g_weather_str[80] = "";
Uint32 g_weather_kicked = 0;     // SDL ticks of the last fetch we launched
time_t g_weather_at = 0;         // wall-clock of the last SUCCESSFUL reading
time_t g_weather_mtime = 0;      // tmp-file mtime we last parsed
Uint32 g_weather_refresh_msg_until = 0;  // show "Refreshing..." until this tick
char   weather_loc[64] = "";     // free text: "Austin, Texas" / "90210" / "" = auto
int    weather_unit = 0;         // 0 = Fahrenheit (USCS), 1 = Celsius (metric); persisted

// Drop a leading '+' from wttr.in's "+72F" (keep '-' for negatives).
static void weather_trim_plus(char *s) {
    if (s[0] == '+') memmove(s, s + 1, strlen(s));
}
static void weather_kick(int force) {
    Uint32 now = SDL_GetTicks();
    Uint32 period = g_weather_str[0] ? WEATHER_PERIOD_MS : WEATHER_RETRY_MS;
    if (!force && g_weather_kicked != 0 && now - g_weather_kicked < period) return;
    g_weather_kicked = now;
    // URL-encode the location: spaces -> '+', keep it simple; wttr.in is lenient.
    char enc[128] = "";
    for (const char *p = weather_loc; *p && strlen(enc) < sizeof(enc) - 4; p++) {
        char e[5];
        if (*p == ' ')                 snprintf(e, sizeof e, "+");
        else if (isalnum((unsigned char)*p) || *p == ',' || *p == '-' || *p == '.')
                                       snprintf(e, sizeof e, "%c", *p);
        else                           snprintf(e, sizeof e, "%%%02X", (unsigned char)*p);
        strncat(enc, e, sizeof(enc) - strlen(enc) - 1);
    }
    const char *u = weather_unit ? "m" : "u";   // wttr.in: ?m metric, ?u USCS
    // Try https first; fall back to http+redirect in case the device has no CA
    // bundle. Only publish a non-empty result.
    char cmd[520];
    snprintf(cmd, sizeof cmd,
        "( curl -sf -m 8 'https://wttr.in/%s?format=%%t+%%C&%s' > " WEATHER_TMP ".tmp 2>/dev/null; "
        "[ -s " WEATHER_TMP ".tmp ] || curl -sfL -m 8 'http://wttr.in/%s?format=%%t+%%C&%s' > " WEATHER_TMP ".tmp 2>/dev/null; "
        "[ -s " WEATHER_TMP ".tmp ] && mv " WEATHER_TMP ".tmp " WEATHER_TMP "; "
        "rm -f " WEATHER_TMP ".tmp ) &", enc, u, enc, u);
    system(cmd);
}
static void weather_read(void) {
    struct stat stt;
    if (stat(WEATHER_TMP, &stt) != 0) return;
    if (stt.st_mtime == g_weather_mtime) return;      // nothing new since last parse
    g_weather_mtime = stt.st_mtime;
    FILE *f = fopen(WEATHER_TMP, "r");
    if (!f) return;
    char buf[80];
    if (fgets(buf, sizeof(buf), f)) {
        buf[strcspn(buf, "\r\n")] = '\0';
        // wttr.in error pages are long HTML; a real reading is short.
        if (buf[0] && strlen(buf) < 60 && !strchr(buf, '<')) {
            weather_trim_plus(buf);
            snprintf(g_weather_str, sizeof(g_weather_str), "%s", buf);
            g_weather_at = time(NULL);
        }
    }
    fclose(f);
}
// Instant local F<->C flip of the cached string so a unit change shows right
// away; the next fetch confirms it.
static void weather_convert_cached(int to_celsius) {
    if (!g_weather_str[0]) return;
    int t; char rest[70] = "";
    if (sscanf(g_weather_str, "%d%69[^\n]", &t, rest) < 1) return;
    // strip a leading degree/unit marker from `rest` (e.g. "°F Sunny")
    char *r = rest;
    while (*r == ' ') r++;
    if ((unsigned char)r[0] == 0xC2 && (unsigned char)r[1] == 0xB0) r += 2;   // U+00B0
    if (*r == 'F' || *r == 'C') r++;
    while (*r == ' ') r++;
    int nt = to_celsius ? (int)((t - 32) * 5.0 / 9.0 + (t >= 32 ? 0.5 : -0.5))
                        : (int)(t * 9.0 / 5.0 + 32 + 0.5);
    snprintf(g_weather_str, sizeof g_weather_str, "%d\xC2\xB0%c %s", nt, to_celsius ? 'C' : 'F', r);
    weather_trim_plus(g_weather_str);
}

// wttr.in's "%C" text is not time-aware -- it says "Sunny" for a clear sky at
// midnight. Rough local-time night window so we can swap in a moon + "Clear".
static int weather_is_night(void) {
    time_t t = time(NULL);
    struct tm *lt = localtime(&t);
    if (!lt) return 0;
    return (lt->tm_hour >= 19 || lt->tm_hour < 6);
}

// Classify a wttr.in "%C" condition string into an icon bucket.
enum { WX_NONE, WX_SUN, WX_PARTLY, WX_CLOUD, WX_RAIN, WX_SNOW, WX_STORM, WX_FOG, WX_WIND, WX_CLEARNIGHT };
static int weather_icon_kind(const char *s) {
    char l[96]; int i = 0;
    for (const char *p = s; *p && i < 95; p++) l[i++] = (char)tolower((unsigned char)*p);
    l[i] = '\0';
    if (strstr(l, "thunder") || strstr(l, "storm"))                       return WX_STORM;
    if (strstr(l, "snow") || strstr(l, "sleet") || strstr(l, "blizzard") ||
        strstr(l, "ice") || strstr(l, "icy"))                            return WX_SNOW;
    if (strstr(l, "rain") || strstr(l, "drizzle") || strstr(l, "shower")) return WX_RAIN;
    if (strstr(l, "fog") || strstr(l, "mist") || strstr(l, "haze") || strstr(l, "smoke")) return WX_FOG;
    if (strstr(l, "wind") || strstr(l, "gale") || strstr(l, "blowing"))   return WX_WIND;
    if (strstr(l, "partly") || strstr(l, "partially"))                    return WX_PARTLY;
    if (strstr(l, "overcast") || strstr(l, "cloud"))                      return WX_CLOUD;
    if (strstr(l, "sunny") || strstr(l, "clear") || strstr(l, "fair"))    return WX_SUN;
    return WX_NONE;
}
static void fill_disc(SDL_Renderer *ren, int cx, int cy, int r) {
    for (int dy = -r; dy <= r; dy++) {
        int dx = (int)(sqrt((double)(r * r - dy * dy)) + 0.5);
        SDL_RenderDrawLine(ren, cx - dx, cy + dy, cx + dx, cy + dy);
    }
}
// Draw a small weather glyph in an s x s box at (x,y). Cheap SDL primitives.
// `bg` is the surface behind it, used to carve the crescent moon.
static void draw_weather_icon(SDL_Renderer *ren, int x, int y, int s, int kind, SDL_Color c, SDL_Color bg) {
    SDL_SetRenderDrawColor(ren, c.r, c.g, c.b, 255);
    int cx = x + s / 2, cy = y + s / 2;
    int cloud_cy = cy + s / 8;

    if (kind == WX_CLEARNIGHT) {
        fill_disc(ren, cx, cy, s / 4);                        // full moon
        SDL_SetRenderDrawColor(ren, bg.r, bg.g, bg.b, 255);
        fill_disc(ren, cx + s / 10, cy - s / 12, s / 4);      // carve the crescent
        SDL_SetRenderDrawColor(ren, c.r, c.g, c.b, 255);
        SDL_RenderDrawPoint(ren, cx + s / 4, cy - s / 4);     // a little star
        SDL_RenderDrawPoint(ren, cx + s / 4 + 1, cy - s / 4);
        return;
    }
    #define WX_CLOUD_SHAPE(off) do { \
        fill_disc(ren, x + s/2 - s/6 + (off), cloud_cy, s/5); \
        fill_disc(ren, x + s/2 + s/6 + (off), cloud_cy, s/6); \
        fill_disc(ren, x + s/2 + (off),        cloud_cy - s/10, s/5); \
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s/6 + (off), cloud_cy, s*2/3, s/4 }); \
    } while (0)

    if (kind == WX_SUN) {
        fill_disc(ren, cx, cy, s / 4);
        for (int a = 0; a < 8; a++) {
            double t = a * 3.14159265 / 4.0;
            int x1 = cx + (int)(cos(t) * s * 0.34), y1 = cy + (int)(sin(t) * s * 0.34);
            int x2 = cx + (int)(cos(t) * s * 0.46), y2 = cy + (int)(sin(t) * s * 0.46);
            SDL_RenderDrawLine(ren, x1, y1, x2, y2);
            SDL_RenderDrawLine(ren, x1 + 1, y1, x2 + 1, y2);
        }
    } else if (kind == WX_PARTLY) {
        fill_disc(ren, x + s/3, y + s/3, s / 6);              // peeking sun
        for (int a = 0; a < 6; a++) {
            double t = a * 3.14159265 / 3.0;
            SDL_RenderDrawLine(ren, x + s/3 + (int)(cos(t)*s*0.22), y + s/3 + (int)(sin(t)*s*0.22),
                                    x + s/3 + (int)(cos(t)*s*0.30), y + s/3 + (int)(sin(t)*s*0.30));
        }
        WX_CLOUD_SHAPE(s/12);
    } else if (kind == WX_CLOUD || kind == WX_FOG || kind == WX_WIND) {
        WX_CLOUD_SHAPE(0);
        if (kind == WX_FOG || kind == WX_WIND) {
            for (int i = 0; i < 3; i++)
                SDL_RenderDrawLine(ren, x + s/6 + (i&1)*s/12, cloud_cy + s/4 + 4 + i*4,
                                        x + s*5/6 - (i&1)*s/12, cloud_cy + s/4 + 4 + i*4);
        }
    } else if (kind == WX_RAIN) {
        WX_CLOUD_SHAPE(0);
        for (int i = 0; i < 3; i++) {
            int rx = x + s/3 + i * s/6;
            SDL_RenderDrawLine(ren, rx, cloud_cy + s/4 + 3, rx - s/12, cloud_cy + s/4 + s/4);
        }
    } else if (kind == WX_SNOW) {
        WX_CLOUD_SHAPE(0);
        for (int i = 0; i < 3; i++) {
            int fx = x + s/3 + i * s/6, fy = cloud_cy + s/4 + s/8;
            SDL_RenderDrawLine(ren, fx - 3, fy, fx + 3, fy);
            SDL_RenderDrawLine(ren, fx, fy - 3, fx, fy + 3);
            SDL_RenderDrawLine(ren, fx - 2, fy - 2, fx + 2, fy + 2);
            SDL_RenderDrawLine(ren, fx - 2, fy + 2, fx + 2, fy - 2);
        }
    } else if (kind == WX_STORM) {
        WX_CLOUD_SHAPE(0);
        SDL_Rect bolt[3] = {
            { cx - 2, cloud_cy + s/4, 4, s/6 },
            { cx - 5, cloud_cy + s/4 + s/8, 8, 3 },
            { cx - 4, cloud_cy + s/4 + s/6, 4, s/8 },
        };
        for (int i = 0; i < 3; i++) SDL_RenderFillRect(ren, &bolt[i]);
    }
    #undef WX_CLOUD_SHAPE
}

// ===================================================================== //
//  Internet radio  --  "local" stations streamed over Wi-Fi via mpv     //
// ===================================================================== //
// The RG34XX has no RF tuner, so "radio in your area" = the online streams
// of stations broadcasting in your region. Location comes from ip-api.com;
// the station directory is radio-browser.info (free, no key). Playback is a
// detached `mpv` process so it keeps going while you browse Snap FE (unless
// the user turns that off in Settings > Sound).
#define RADIO_MAX 90
#define RADIO_LOC_TMP  "/tmp/snapos-radio-loc.txt"
#define RADIO_LIST_TMP "/tmp/snapos-radio.json"
#define RADIO_BUSY     "/tmp/snapos-radio.busy"

struct RadioStation { char name[76]; char url[420]; char codec[10]; int bitrate; };
struct RadioStation radio_stations[RADIO_MAX];
int    radio_count = 0;
int    radio_sel = 0;
int    radio_playing_idx = -1;
int    radio_pid = 0;              // mpv pid, 0 = stopped
int    radio_loading = 0;
int    radio_persist = 1;         // keep playing while browsing (persisted)
int    radio_over_games = 0;      // persisted: keep radio alive during a game
int    radio_game_audio = 1;      // persisted: retain game effects under radio
int    radio_volume_pct = 100;    // persisted; applied when a station starts (0..150)
char   radio_place[80] = "";      // "City, Region" for the header
char   radio_now[80] = "";        // station name currently playing
char   radio_status[128] = "";
Uint32 radio_fetch_started = 0;
Uint32 radio_started_at = 0;      // when the current mpv was spawned
int    radio_vol_dirty = 0;       // volume changed -> restart stream to apply
Uint32 radio_vol_at = 0;
time_t radio_list_mtime = 0;

static int json_str_field(const char *obj, const char *key, char *out, int n) {
    char pat[40]; snprintf(pat, sizeof pat, "\"%s\":\"", key);
    const char *s = strstr(obj, pat);
    if (!s) { if (n) out[0] = 0; return 0; }
    s += strlen(pat);
    int o = 0;
    while (*s && *s != '"' && o < n - 1) {
        if (*s == '\\') {
            s++;
            if (!*s) break;
            if (*s == 'n' || *s == 't' || *s == 'r') out[o++] = ' ';
            else if (*s == 'u') { s += 4; out[o++] = '?'; }
            else out[o++] = *s;
            s++;
        } else out[o++] = *s++;
    }
    out[o] = 0;
    return o > 0;
}
static int json_int_field(const char *obj, const char *key) {
    char pat[40]; snprintf(pat, sizeof pat, "\"%s\":", key);
    const char *s = strstr(obj, pat);
    if (!s) return 0;
    s += strlen(pat);
    while (*s == ' ') s++;
    return atoi(s);
}
static void radio_read_location(void) {
    FILE *f = fopen(RADIO_LOC_TMP, "r");
    if (!f) return;
    char cc[48] = "", rg[64] = "", ci[64] = "";
    if (!fgets(cc, sizeof cc, f)) { fclose(f); return; }
    fgets(rg, sizeof rg, f);
    fgets(ci, sizeof ci, f);
    fclose(f);
    rg[strcspn(rg, "\r\n")] = 0;
    ci[strcspn(ci, "\r\n")] = 0;
    if (ci[0] || rg[0])
        snprintf(radio_place, sizeof radio_place, "%s%s%s", ci, (ci[0] && rg[0]) ? ", " : "", rg);
}
static void radio_parse(void) {
    FILE *f = fopen(RADIO_LIST_TMP, "rb");
    if (!f) return;
    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    if (sz <= 2 || sz > 4L * 1024 * 1024) { fclose(f); return; }
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return; }
    size_t got = fread(buf, 1, (size_t)sz, f); buf[got] = 0; fclose(f);

    radio_count = 0;
    const char *p = buf;
    while (radio_count < RADIO_MAX) {
        const char *a = strstr(p, "\"stationuuid\"");
        if (!a) break;
        const char *nb = strstr(a + 13, "\"stationuuid\"");
        int objlen = nb ? (int)(nb - a) : (int)strlen(a);
        char obj[4096];
        int cl = objlen < (int)sizeof(obj) - 1 ? objlen : (int)sizeof(obj) - 1;
        memcpy(obj, a, cl); obj[cl] = 0;

        struct RadioStation st; memset(&st, 0, sizeof st);
        json_str_field(obj, "name", st.name, sizeof st.name);
        if (!json_str_field(obj, "url_resolved", st.url, sizeof st.url))
            json_str_field(obj, "url", st.url, sizeof st.url);
        json_str_field(obj, "codec", st.codec, sizeof st.codec);
        st.bitrate = json_int_field(obj, "bitrate");
        // trim leading/trailing spaces in the name
        char *nm = st.name; while (*nm == ' ') nm++;
        if (nm != st.name) memmove(st.name, nm, strlen(nm) + 1);
        for (int i = (int)strlen(st.name) - 1; i >= 0 && st.name[i] == ' '; i--) st.name[i] = 0;

        if (st.name[0] && strncmp(st.url, "http", 4) == 0) {
            int dup = 0;
            for (int i = 0; i < radio_count; i++)
                if (strcasecmp(radio_stations[i].name, st.name) == 0) { dup = 1; break; }
            if (!dup) radio_stations[radio_count++] = st;
        }
        if (!nb) break;
        p = nb;
    }
    free(buf);
    if (radio_sel >= radio_count) radio_sel = radio_count ? radio_count - 1 : 0;
    snprintf(radio_status, sizeof radio_status,
             radio_count ? "%d stations" : "No stations found -- try Search", radio_count);
}

#ifdef SNAPOS_TARGET_KNULLI
// Knulli regenerates retroarchcustom.cfg before every game.  Preserve each
// RetroArch hotkey independently so changing one binding in RetroArch cannot
// reset the others on the next launch.  Snap owns the one-time defaults only;
// after migration, RetroArch/the user owns every stored value.
typedef struct {
    const char *key;
    char value[24];
    int set;
} RaHotkey;

static RaHotkey ra_hotkeys[] = {
    { "input_enable_hotkey_btn",          "", 0 },
    { "input_menu_toggle_btn",            "", 0 },
    { "input_exit_emulator_btn",          "", 0 },
    { "input_hold_fast_forward_btn",      "", 0 },
    { "input_toggle_fast_forward_btn",    "", 0 },
    { "input_shader_next_btn",            "", 0 },
    { "input_shader_prev_btn",            "", 0 },
    { "input_save_state_btn",             "", 0 },
    { "input_load_state_btn",             "", 0 },
    { "input_state_slot_increase_btn",    "", 0 },
    { "input_state_slot_decrease_btn",    "", 0 },
    { "input_rewind_btn",                 "", 0 },
    { "input_pause_toggle_btn",           "", 0 },
    { "input_reset_btn",                  "", 0 },
    { "input_screenshot_btn",             "", 0 },
    { "input_frame_advance_btn",          "", 0 },
    { "input_audio_mute_btn",             "", 0 },
    { "input_ai_service_btn",             "", 0 },
    { "input_recording_toggle_btn",       "", 0 },
    { "input_streaming_toggle_btn",       "", 0 },
    { "input_cheat_index_plus_btn",       "", 0 },
    { "input_cheat_index_minus_btn",      "", 0 },
    { "input_cheat_toggle_btn",           "", 0 },
    { "input_netplay_game_watch_btn",     "", 0 },
    { "input_disk_eject_toggle_btn",      "", 0 },
    { "input_disk_next_btn",              "", 0 },
    { "input_disk_prev_btn",              "", 0 },
    { "input_grab_mouse_toggle_btn",      "", 0 },
    { "input_game_focus_toggle_btn",      "", 0 },
    { "input_desktop_menu_toggle_btn",    "", 0 },
    { "input_fps_toggle_btn",             "", 0 },
    { "input_send_debug_info_btn",        "", 0 },
    { "input_close_content_btn",          "", 0 },
    { "input_overlay_next_btn",           "", 0 },
    { "input_volume_up_btn",              "", 0 },
    { "input_volume_down_btn",            "", 0 },
    { "input_hotkey_block_delay",         "", 0 }
};
#define RA_HOTKEY_COUNT ((int)(sizeof(ra_hotkeys) / sizeof(ra_hotkeys[0])))
static int ra_hotkeys_loaded = 0;
static void ra_hotkeys_load(void);

static int ra_hotkey_value_valid(const char *v) {
    if (!v || !*v) return 0;
    // RetroArch uses numeric buttons, signed axes, and hat values such as
    // h0up.  Keep the full normal token set so a user remap made in RetroArch
    // can round-trip through SNAP instead of being quietly dropped.
    for (const char *p = v; *p; p++) {
        if (!(isalnum((unsigned char)*p) || *p == '_' || *p == '+' || *p == '-'))
            return 0;
    }
    return 1;
}

static int ra_hotkey_index(const char *key) {
    for (int i = 0; i < RA_HOTKEY_COUNT; i++)
        if (strcmp(ra_hotkeys[i].key, key) == 0) return i;
    return -1;
}

static void ra_hotkey_set(const char *key, const char *value) {
    int i = ra_hotkey_index(key);
    if (i < 0 || !ra_hotkey_value_valid(value)) return;
    snprintf(ra_hotkeys[i].value, sizeof ra_hotkeys[i].value, "%s", value);
    ra_hotkeys[i].set = 1;
}

static int ra_cfg_read_value(const char *path, const char *key, char *out, size_t outsz) {
    FILE *f = fopen(path, "r");
    if (!f) return 0;
    char line[512]; int found = 0; size_t kl = strlen(key);
    while (fgets(line, sizeof line, f)) {
        char *p = line;
        while (*p && isspace((unsigned char)*p)) p++;
        if (strncmp(p, key, kl) != 0) continue;
        p += kl;
        while (*p && isspace((unsigned char)*p)) p++;
        if (*p++ != '=') continue;
        while (*p && isspace((unsigned char)*p)) p++;
        char quote = (*p == '\'' || *p == '"') ? *p++ : 0;
        char *e = p;
        if (quote) while (*e && *e != quote && *e != '\r' && *e != '\n') e++;
        else while (*e && !isspace((unsigned char)*e) && *e != '#') e++;
        *e = '\0';
        if (ra_hotkey_value_valid(p)) { snprintf(out, outsz, "%s", p); found = 1; }
    }
    fclose(f);
    return found;
}

static const char *ra_hotkeys_state_path(void) {
    return "/userdata/system/snapos/config/retroarch-hotkeys.cfg";
}

static void ra_hotkeys_save(void) {
    FILE *f = fopen(ra_hotkeys_state_path(), "w");
    if (!f) return;
    fprintf(f, "format_version=3\n");
    for (int i = 0; i < RA_HOTKEY_COUNT; i++)
        if (ra_hotkeys[i].set)
            fprintf(f, "%s=%s\n", ra_hotkeys[i].key, ra_hotkeys[i].value);
    fclose(f);
}

// Called only when the user changes SNAP's fast-forward controls.  Normal game
// launches never call this, so a custom RetroArch binding remains untouched.
static void ra_hotkeys_set_snap_fastforward(void) {
    ra_hotkeys_load();
    int ffi = (fast_forward_idx >= 0 && fast_forward_idx < FASTFORWARD_COUNT) ? fast_forward_idx : 1;
    if (fast_forward_values[ffi] == 0) {
        ra_hotkey_set("input_hold_fast_forward_btn", "nul");
        ra_hotkey_set("input_toggle_fast_forward_btn", "nul");
    } else if (fast_forward_mode) {
        ra_hotkey_set("input_hold_fast_forward_btn", "nul");
        ra_hotkey_set("input_toggle_fast_forward_btn", "14");
    } else {
        ra_hotkey_set("input_hold_fast_forward_btn", "14");
        ra_hotkey_set("input_toggle_fast_forward_btn", "nul");
    }
    // R2 cannot be both fast-forward and shader-next.
    int sn = ra_hotkey_index("input_shader_next_btn");
    int sp = ra_hotkey_index("input_shader_prev_btn");
    if (sn >= 0 && ra_hotkeys[sn].set && strcmp(ra_hotkeys[sn].value, "14") == 0)
        ra_hotkey_set("input_shader_next_btn", "nul");
    if (sp >= 0 && ra_hotkeys[sp].set && strcmp(ra_hotkeys[sp].value, "14") == 0)
        ra_hotkey_set("input_shader_prev_btn", "nul");
    ra_hotkeys_save();
}

static void ra_hotkeys_load(void) {
    if (ra_hotkeys_loaded) return;
    ra_hotkeys_loaded = 1;
    char value[24] = "", version[24] = "";
    int v3 = ra_cfg_read_value(ra_hotkeys_state_path(), "format_version", version, sizeof version) &&
             strcmp(version, "3") == 0;
    if (v3) {
        for (int i = 0; i < RA_HOTKEY_COUNT; i++)
            if (ra_cfg_read_value(ra_hotkeys_state_path(), ra_hotkeys[i].key,
                                  value, sizeof value))
                ra_hotkey_set(ra_hotkeys[i].key, value);
        return;
    }

    // Migration: import existing user bindings, then repair the two invalid
    // SNAP defaults shipped in the previous bridge.  Version 3 is written on
    // exit, after which a user's own RetroArch changes remain untouched.
    const char *cfg = "/userdata/system/configs/retroarch/retroarchcustom.cfg";
    for (int i = 0; i < RA_HOTKEY_COUNT; i++)
        if (ra_cfg_read_value(cfg, ra_hotkeys[i].key, value, sizeof value))
            ra_hotkey_set(ra_hotkeys[i].key, value);
    if (ra_cfg_read_value(ra_hotkeys_state_path(), "input_enable_hotkey_btn", value, sizeof value))
        ra_hotkey_set("input_enable_hotkey_btn", value);

    // Knulli's standard H700 layout: Menu is the hotkey modifier, Menu+Select
    // opens RetroArch, Menu+Start exits, and Menu+R2 fast-forwards.
    ra_hotkey_set("input_enable_hotkey_btn", "11");
    ra_hotkey_set("input_menu_toggle_btn", "9");
    ra_hotkey_set("input_exit_emulator_btn", "10");
    ra_hotkey_set("input_hotkey_block_delay", "6");
    ra_hotkey_set("input_shader_next_btn", "nul");
    ra_hotkey_set("input_shader_prev_btn", "nul");
    ra_hotkey_set("input_volume_up_btn", "nul");
    ra_hotkey_set("input_volume_down_btn", "nul");
    if (fast_forward_values[(fast_forward_idx >= 0 && fast_forward_idx < FASTFORWARD_COUNT) ? fast_forward_idx : 1] == 0) {
        ra_hotkey_set("input_hold_fast_forward_btn", "nul");
        ra_hotkey_set("input_toggle_fast_forward_btn", "nul");
    } else if (fast_forward_mode) {
        ra_hotkey_set("input_hold_fast_forward_btn", "nul");
        ra_hotkey_set("input_toggle_fast_forward_btn", "14");
    } else {
        ra_hotkey_set("input_hold_fast_forward_btn", "14");
        ra_hotkey_set("input_toggle_fast_forward_btn", "nul");
    }
    ra_hotkeys_save();
}

static void ra_hotkeys_capture(void) {
    ra_hotkeys_load();
    const char *cfg = "/userdata/system/configs/retroarch/retroarchcustom.cfg";
    char value[24]; int changed = 0;
    for (int i = 0; i < RA_HOTKEY_COUNT; i++) {
        if (!ra_cfg_read_value(cfg, ra_hotkeys[i].key, value, sizeof value)) continue;
        if (!ra_hotkeys[i].set || strcmp(value, ra_hotkeys[i].value) != 0) {
            ra_hotkey_set(ra_hotkeys[i].key, value);
            changed = 1;
        }
    }
    if (changed) ra_hotkeys_save();
}

// RetroArch's bare menu and Knulli's per-game configgen start from different
// configuration files.  Keep user-selected global options in a small SNAP
// profile, then layer that profile into both entry points.  Hotkeys remain in
// their dedicated file above because SNAP must reserve Menu+Volume for panel
// brightness even when the rest of RetroArch is user-owned.
static const char *ra_user_settings_path(void) {
    return "/userdata/system/snapos/config/retroarch-user.cfg";
}

static int ra_line_key(const char *line, char *key, size_t key_sz, const char **value) {
    const char *p = line;
    while (*p && isspace((unsigned char)*p)) p++;
    if (!*p || *p == '#') return 0;
    const char *start = p;
    while (*p && (isalnum((unsigned char)*p) || *p == '_')) p++;
    size_t n = (size_t)(p - start);
    if (!n || n >= key_sz) return 0;
    while (*p && isspace((unsigned char)*p)) p++;
    if (*p++ != '=') return 0;
    while (*p && isspace((unsigned char)*p)) p++;
    memcpy(key, start, n); key[n] = '\0';
    if (value) *value = p;
    return 1;
}

// Knulli's top-level keys contain dots (for example global.retroarch.video_*),
// unlike RetroArch's underscore-only keys parsed above. Extract the complete
// left-hand side so a bloated file can be compacted without changing which
// value wins: for duplicate keys Knulli uses the last one, and so do we.
static int knulli_line_key(const char *line, char *key, size_t key_sz) {
    const char *p = line;
    while (*p && isspace((unsigned char)*p)) p++;
    if (!*p || *p == '#') return 0;
    const char *eq = strchr(p, '=');
    if (!eq) return 0;
    const char *end = eq;
    while (end > p && isspace((unsigned char)end[-1])) end--;
    size_t n = (size_t)(end - p);
    if (!n || n >= key_sz) return 0;
    memcpy(key, p, n); key[n] = '\0';
    return 1;
}

static int ra_hotkey_key(const char *key) {
    return ra_hotkey_index(key) >= 0;
}

static int ra_user_setting_allowed(const char *key) {
    // This is deliberately a small allow-list, not "everything except input".
    // configgen regenerates controller, driver and path values every launch;
    // copying any one of those between the standalone menu and a game can
    // break the RG34XX-SP's direct controller map.  The list below contains
    // only portable user preferences which are useful in both entry points.
    static const char *exact[] = {
        "config_save_on_exit", "video_font_enable", "menu_enable_widgets",
        "menu_widget_enable", "audio_volume", "audio_latency", "video_smooth",
        "video_vsync", "video_hard_sync", "video_frame_delay_auto",
        "rewind_enable", "run_ahead_enabled", "run_ahead_frames",
        "preemptive_frames_enable", "preemptive_frames", "savestate_auto_save",
        "savestate_auto_load", "savestate_auto_index", "autosave_interval",
        "state_slot", "quit_press_twice", "rgui_extended_ascii",
        "rgui_show_start_screen", NULL
    };
    static const char *prefix[] = {
        "notification_", "video_message_", "ozone_", "rgui_", "xmb_",
        "materialui_", "menu_show_", "content_show_", NULL
    };
    if (!key || !*key || ra_hotkey_key(key)) return 0;
    for (int i = 0; exact[i]; i++) if (strcmp(key, exact[i]) == 0) return 1;
    for (int i = 0; prefix[i]; i++)
        if (strncmp(key, prefix[i], strlen(prefix[i])) == 0) return 1;
    return 0;
}

static void ra_user_settings_capture(void) {
    const char *src = "/userdata/system/configs/retroarch/retroarchcustom.cfg";
    FILE *in = fopen(src, "r");
    if (!in) return;
    // /userdata is an exFAT/FUSE volume on many H700 installs. Its atomic
    // rename behavior is not reliable across every mount configuration, so
    // write the tiny portable-preferences profile directly.
    FILE *out = fopen(ra_user_settings_path(), "w");
    if (!out) { fclose(in); return; }
    char line[1024], key[160];
    while (fgets(line, sizeof line, in)) {
        if (!ra_line_key(line, key, sizeof key, NULL) || !ra_user_setting_allowed(key)) continue;
        char *p = line; while (*p && isspace((unsigned char)*p)) p++;
        p[strcspn(p, "\r\n")] = '\0';
        fprintf(out, "%s\n", p);
    }
    fclose(in); fclose(out);
}

static void ra_user_settings_append(FILE *out, int knulli_format) {
    FILE *in = fopen(ra_user_settings_path(), "r");
    if (!in) return;
    char line[1024], key[160]; const char *value;
    while (fgets(line, sizeof line, in)) {
        if (!ra_line_key(line, key, sizeof key, &value) || !ra_user_setting_allowed(key)) continue;
        char clean[1024]; snprintf(clean, sizeof clean, "%s", value);
        clean[strcspn(clean, "\r\n")] = '\0';
        if (knulli_format) fprintf(out, "global.retroarch.%s=%s\n", key, clean);
        else fprintf(out, "%s = %s\n", key, clean);
    }
    fclose(in);
}

// Put the persisted user options and bindings into RetroArch's menu
// configuration before the standalone Home app launches. Games receive the
// same options through configgen/knulli.conf below.
static void ra_hotkeys_apply_to_cfg(const char *path) {
    ra_hotkeys_load();
    // First open seeds the profile from Knulli's generated configuration.
    // Later calls merely apply the user profile captured when RetroArch exits.
    if (access(ra_user_settings_path(), R_OK) != 0) ra_user_settings_capture();
    char tmp[1024]; snprintf(tmp, sizeof tmp, "%s.snapos-new", path);
    FILE *in = fopen(path, "r");
    FILE *out = fopen(tmp, "w");
    if (!out) { if (in) fclose(in); return; }
    if (in) {
        char line[1024];
        while (fgets(line, sizeof line, in)) {
            char *p = line;
            while (*p && isspace((unsigned char)*p)) p++;
            char key[160];
            int owned = ra_line_key(p, key, sizeof key, NULL) &&
                        (ra_hotkey_key(key) || ra_user_setting_allowed(key) ||
                         strcmp(key, "input_autodetect_enable") == 0 ||
                         strcmp(key, "input_joypad_driver") == 0 ||
                         strcmp(key, "joypad_autoconfig_dir") == 0);
            if (!owned) fputs(line, out);
        }
        fclose(in);
    }
    ra_user_settings_append(out, 0);
    for (int i = 0; i < RA_HOTKEY_COUNT; i++)
        if (ra_hotkeys[i].set)
            fprintf(out, "%s = \"%s\"\n", ra_hotkeys[i].key, ra_hotkeys[i].value);
    // Knulli/configgen writes the RG34XX-SP's direct controller mapping.  Do
    // not ask RetroArch to search for an extra autoconfig profile here: it
    // produces the false "controller not configured" notice on game launch.
    fprintf(out, "input_joypad_driver = udev\n");
    fprintf(out, "input_autodetect_enable = \"false\"\n");
    // A clean RetroArch exit is a second safety net if the user adjusts a
    // setting and leaves through Menu+Start rather than pressing Save.
    fprintf(out, "config_save_on_exit = \"true\"\n");
    fclose(out);
    rename(tmp, path);
}

// Push Snap's per-launch RetroArch settings into Knulli's batocera.conf --
// configgen bakes any global.* / global.retroarch.* key straight into the
// generated retroarchcustom.cfg for the next launch. SNAP owns only its audio,
// speed, and protected-button values; the user's general RetroArch settings
// are merged from the shared profile below.
//   on != 0 -> mute the game's own audio (radio/music plays over it instead)
// aspect/rotation are resolved SNAP indices for the game about to launch.
static void game_audio_mute(int on, int aspect, int rotation) {
    const char *path = "/userdata/system/knulli.conf";
    ra_hotkeys_load();
    if (access(ra_user_settings_path(), R_OK) != 0) ra_user_settings_capture();

    // Hotfix 2 briefly mirrored an entire generated retroarchcustom.cfg back
    // into knulli.conf.  Affected devices now carry 800+ global.retroarch.*
    // overrides (a normal hand-edited file has only a handful), so every game
    // is rebuilt from stale generated state and user changes can be masked.
    // Migrate only the unmistakably polluted case, preserving an exact backup;
    // small legitimate user override sets are never touched.
    int retroarch_override_lines = 0;
    {
        static const char prefix[] = "global.retroarch.";
        FILE *probe = fopen(path, "r");
        char line[1024];
        if (probe) {
            while (fgets(line, sizeof line, probe))
                if (strncmp(line, prefix, sizeof(prefix) - 1) == 0)
                    retroarch_override_lines++;
            fclose(probe);
        }
    }
    int purge_polluted_retroarch = retroarch_override_lines > 256;
    if (purge_polluted_retroarch) {
        const char *backup = "/userdata/system/knulli.conf.snapfe-pre-cleanup";
        if (access(backup, F_OK) != 0) {
            FILE *src = fopen(path, "rb"), *dst = src ? fopen(backup, "wb") : NULL;
            if (src && dst) {
                char buf[8192]; size_t n;
                while ((n = fread(buf, 1, sizeof buf, src)) > 0)
                    if (fwrite(buf, 1, n, dst) != n) break;
            }
            if (dst) fclose(dst);
            if (src) fclose(src);
        }
    }

    // Avoid rewriting the large configuration on every launch. On exFAT that
    // synchronous read/write was a noticeable part of the black loading gap.
    // Rebuild only when SNAP's values, its shared RA profiles, or knulli.conf
    // itself actually changed.
    if (aspect < 0 || aspect > 4) aspect = 0;
    if (rotation < 0 || rotation > 3) rotation = 0;
    static int cache_valid = 0, cache_on = -1, cache_ff = -1, cache_ff_mode = -1;
    static int cache_aspect = -1, cache_rotation = -1;
    static long cache_user_mtime = -1, cache_hotkey_mtime = -1, cache_knulli_mtime = -1;
    long user_mtime = sn_path_mtime(ra_user_settings_path());
    long hotkey_mtime = sn_path_mtime(ra_hotkeys_state_path());
    long knulli_mtime = sn_path_mtime(path);
    if (cache_valid && cache_on == !!on && cache_ff == fast_forward_idx &&
        cache_ff_mode == fast_forward_mode && cache_aspect == aspect && cache_rotation == rotation &&
        cache_user_mtime == user_mtime &&
        cache_hotkey_mtime == hotkey_mtime && cache_knulli_mtime == knulli_mtime)
        return;
    // Audio + speed are SNAP-owned. Hotkey values are user-owned but mirrored
    // here so configgen can rebuild RetroArch without losing them.
    static const char *OWN[] = {
        "global.retroarch.audio_mute_enable",
        "global.retroarch.fastforward_ratio",
        "global.retroarch.fastforward_frameskip",
        "global.retroarch.input_autodetect_enable",
        "global.retroarch.input_joypad_driver",
        "global.retroarch.joypad_autoconfig_dir",
        "global.retroarch.config_save_on_exit",
        "global.retroarch.aspect_ratio_index",
        "global.retroarch.video_aspect_ratio",
        "global.retroarch.video_aspect_ratio_auto",
        "global.retroarch.video_scale_integer",
        "global.retroarch.video_force_aspect",
        "global.retroarch.video_rotation",
        NULL
    };
    static const char *LEGACY[] = {
        "global.retroarch.input_hold_fast_forward_btn=14",
        "global.retroarch.input_hold_fast_forward_btn=nul",
        "global.retroarch.input_toggle_fast_forward_btn=14",
        "global.retroarch.input_toggle_fast_forward_btn=nul",
        "global.retroarch.input_shader_next_btn=nul",
        "global.retroarch.input_shader_prev_btn=nul",
        "global.retroarch.input_hotkey_block_delay=6",
        "global.retroarch.input_volume_up_btn=nul",
        "global.retroarch.input_volume_down_btn=nul",
        "global.toggle_fast_forward=14",
        "global.retroarch.network_cmd_enable=true",
        "global.retroarch.network_cmd_port=55355",
        NULL
    };
    typedef struct { char *text; char key[192]; int keyed; } KnulliLine;
    KnulliLine *keep = NULL;
    int kl = 0, kcap = 0;
    int source_existed = access(path, F_OK) == 0;
    struct stat source_stat;
    int have_source_stat = stat(path, &source_stat) == 0;
    FILE *f = fopen(path, "r");
    // A transient read/permission error must never turn into an empty system
    // configuration. Leave the last known-good file untouched and retry next
    // launch instead.
    if (!f && source_existed) return;
    if (f) {
        char line[1024];
        while (fgets(line, sizeof line, f)) {
            int owned = 0;
            for (int i = 0; OWN[i]; i++) if (strncmp(line, OWN[i], strlen(OWN[i])) == 0) { owned = 1; break; }
            if (!owned) {
                for (int i = 0; i < RA_HOTKEY_COUNT; i++) {
                    char full[96]; snprintf(full, sizeof full, "global.retroarch.%s", ra_hotkeys[i].key);
                    size_t n = strlen(full);
                    if (strncmp(line, full, n) == 0 && (line[n] == '=' || isspace((unsigned char)line[n]))) {
                        owned = 1; break;
                    }
                }
            }
            static const char RA_GLOBAL[] = "global.retroarch.";
            if (!owned && strncmp(line, RA_GLOBAL, sizeof(RA_GLOBAL) - 1) == 0) {
                char key[160];
                if (ra_line_key(line + sizeof(RA_GLOBAL) - 1, key, sizeof key, NULL) &&
                    ra_user_setting_allowed(key)) owned = 1;
            }
            if (!owned && purge_polluted_retroarch &&
                strncmp(line, RA_GLOBAL, sizeof(RA_GLOBAL) - 1) == 0)
                owned = 1;
            if (!owned) {
                char clean[1024]; snprintf(clean, sizeof clean, "%s", line);
                clean[strcspn(clean, "\r\n")] = '\0';
                for (int i = 0; LEGACY[i]; i++) if (strcmp(clean, LEGACY[i]) == 0) { owned = 1; break; }
            }
            if (owned) continue;
            if (kl >= kcap) {
                int next = kcap ? kcap * 2 : 512;
                KnulliLine *grown = realloc(keep, (size_t)next * sizeof *grown);
                if (!grown) continue;
                keep = grown; kcap = next;
            }
            keep[kl].text = strdup(line);
            if (!keep[kl].text) continue;
            keep[kl].keyed = knulli_line_key(line, keep[kl].key, sizeof keep[kl].key);
            kl++;
        }
        fclose(f);
    }
    const char *tmp_path = "/userdata/system/knulli.conf.snapfe-tmp";
    FILE *w = fopen(tmp_path, "w");
    if (!w) {
        for (int i = 0; i < kl; i++) free(keep[i].text);
        free(keep);
        return;
    }
    if (have_source_stat) fchmod(fileno(w), source_stat.st_mode & 0777);
    int wrote = 0;
    for (int i = 0; i < kl; i++) {
        int shadowed = 0;
        if (keep[i].keyed) {
            for (int j = i + 1; j < kl; j++)
                if (keep[j].keyed && strcmp(keep[i].key, keep[j].key) == 0) {
                    shadowed = 1; break;
                }
        }
        if (!shadowed) { fputs(keep[i].text, w); wrote = 1; }
        free(keep[i].text);
    }
    free(keep);
    if (wrote) fputc('\n', w);

    // Always explicit -- never just "absent" -- so a crash mid-game can't leave
    // every future launch muted.
    fprintf(w, "global.retroarch.audio_mute_enable=%s\n", on ? "true" : "false");
    fprintf(w, "global.retroarch.input_joypad_driver=udev\n");
    fprintf(w, "global.retroarch.input_autodetect_enable=false\n");

    for (int i = 0; i < RA_HOTKEY_COUNT; i++)
        if (ra_hotkeys[i].set)
            fprintf(w, "global.retroarch.%s=%s\n", ra_hotkeys[i].key, ra_hotkeys[i].value);
    ra_user_settings_append(w, 1);
    fprintf(w, "global.retroarch.config_save_on_exit=true\n");

    // Fast-forward speed is safe to own; the button that triggers it is not.
    int ffi = (fast_forward_idx >= 0 && fast_forward_idx < FASTFORWARD_COUNT) ? fast_forward_idx : 1;
    int ffv = fast_forward_values[ffi];
    double ratio = (ffv == 0) ? 1.0 : (ffv < 0) ? 0.0 : (double)ffv;
    fprintf(w, "global.retroarch.fastforward_ratio=%.6f\n", ratio);
    if (ffv != 0) {
        fprintf(w, "global.retroarch.fastforward_frameskip=true\n");
    }

    // Knulli launches games through configgen, so the desktop append-config
    // file is never read on this device. Put the selected geometry into the
    // source configgen actually consumes. Core Default deliberately leaves the
    // aspect keys absent; every explicit choice is forced for predictable
    // results across native 3:2 and 4:3 panels.
    if (aspect != 0) {
        static const int ra_index[5] = { 22, 0, 7, 1, 21 };
        static const double ratio[5] = { 1.3333, 1.3333, 1.5, 1.7778, 1.3333 };
        fprintf(w, "global.retroarch.aspect_ratio_index=%d\n", ra_index[aspect]);
        fprintf(w, "global.retroarch.video_aspect_ratio=%.4f\n", ratio[aspect]);
        fprintf(w, "global.retroarch.video_aspect_ratio_auto=false\n");
        fprintf(w, "global.retroarch.video_scale_integer=%s\n", aspect == 4 ? "true" : "false");
        fprintf(w, "global.retroarch.video_force_aspect=true\n");
    }
    if (rotation != 0)
        fprintf(w, "global.retroarch.video_rotation=%d\n", rotation);
    if (fclose(w) != 0 || rename(tmp_path, path) != 0) {
        unlink(tmp_path);
        return;
    }
    cache_valid = 1;
    cache_on = !!on;
    cache_ff = fast_forward_idx;
    cache_ff_mode = fast_forward_mode;
    cache_aspect = aspect;
    cache_rotation = rotation;
    cache_user_mtime = user_mtime;
    cache_hotkey_mtime = hotkey_mtime;
    cache_knulli_mtime = sn_path_mtime(path);
}
static void radio_stop(void) {
    if (radio_pid > 0) {
        kill(-radio_pid, SIGTERM);
        kill(radio_pid, SIGTERM);
        for (int i = 0; i < 10 && waitpid(radio_pid, NULL, WNOHANG) == 0; i++) usleep(20000);
        kill(-radio_pid, SIGKILL);
        waitpid(radio_pid, NULL, WNOHANG);
    }
    radio_pid = 0;
    radio_playing_idx = -1;
    radio_now[0] = 0;
}
static void radio_play(int idx) {
    if (idx < 0 || idx >= radio_count) return;
    radio_stop();
    int v = radio_volume_pct < 0 ? 0 : radio_volume_pct > 150 ? 150 : radio_volume_pct;
    char vol[24]; snprintf(vol, sizeof vol, "--volume=%d", v);
    const char *url = radio_stations[idx].url;
    pid_t pid = fork();
    if (pid == 0) {
        setsid();
        int nul = open("/dev/null", O_RDWR);
        if (nul >= 0) { dup2(nul, 0); dup2(nul, 1); dup2(nul, 2); }
        setenv("XDG_RUNTIME_DIR", "/var/run", 1);
        // mpv 0.40 dropped --input-file; volume is set at spawn and applied by
        // a debounced restart on change (see radio_poll).
        execlp("mpv", "mpv", "--no-video", "--no-terminal", "--really-quiet",
               "--idle=no", "--cache=yes", "--network-timeout=15",
               "--audio-display=no", "--volume-max=200", "--replaygain=no",
               vol, "--", url, (char *)NULL);
        execlp("ffplay", "ffplay", "-nodisp", "-autoexit", "-loglevel", "quiet", url, (char *)NULL);
        _exit(127);
    }
    if (pid < 0) { snprintf(radio_status, sizeof radio_status, "Could not start player"); return; }
    radio_pid = pid;
    radio_playing_idx = idx;
    radio_started_at = SDL_GetTicks();
    radio_vol_dirty = 0;
    snprintf(radio_now, sizeof radio_now, "%s", radio_stations[idx].name);
    snprintf(radio_status, sizeof radio_status, "Connecting: %s", radio_now);
}
static void radio_apply_volume(void) {
    // mpv can't be told live any more -- mark it and let radio_poll restart the
    // stream once the user stops nudging the slider.
    if (radio_pid > 0) { radio_vol_dirty = 1; radio_vol_at = SDL_GetTicks(); }
}
static void radio_refresh(const char *search) {
    radio_loading = 1;
    radio_fetch_started = SDL_GetTicks();
    snprintf(radio_status, sizeof radio_status, search && search[0] ? "Searching..." : "Finding stations near you...");
    char cmd[1500];
    const char *m1 = "https://de1.api.radio-browser.info/json/stations";
    const char *m2 = "https://nl1.api.radio-browser.info/json/stations";
    const char *P  = "hidebroken=true&order=votes&reverse=true&limit=90";
    if (search && search[0]) {
        char enc[220] = "";
        for (const char *q = search; *q && strlen(enc) < sizeof(enc) - 4; q++) {
            char e[4];
            if (isalnum((unsigned char)*q)) snprintf(e, sizeof e, "%c", *q);
            else snprintf(e, sizeof e, "%%%02X", (unsigned char)*q);
            strncat(enc, e, sizeof(enc) - strlen(enc) - 1);
        }
        snprintf(cmd, sizeof cmd,
            "touch %s; ( curl -sf -m 15 -A SnapFE/1.0 \"%s/byname/%s?%s\" > %s.t; "
            "[ -s %s.t ] || curl -sf -m 15 -A SnapFE/1.0 \"%s/byname/%s?%s\" > %s.t; "
            "[ -s %s.t ] && mv %s.t %s; rm -f %s.t %s ) &",
            RADIO_BUSY, m1, enc, P, RADIO_LIST_TMP,
            RADIO_LIST_TMP, m2, enc, P, RADIO_LIST_TMP,
            RADIO_LIST_TMP, RADIO_LIST_TMP, RADIO_LIST_TMP, RADIO_LIST_TMP, RADIO_BUSY);
    } else {
        // ip-api /line/ with fields=countryCode,regionName,city,lat,lon comes
        // back in that canonical order, one per line.
        snprintf(cmd, sizeof cmd,
            "touch %s; ( G=$(curl -sf -m 8 \"http://ip-api.com/line/?fields=countryCode,regionName,city,lat,lon\"); "
            "printf '%%s\\n' \"$G\" > %s; "
            "CC=$(printf '%%s\\n' \"$G\" | sed -n 1p); "
            "RG=$(printf '%%s\\n' \"$G\" | sed -n 2p | sed 's/ /%%20/g'); "
            "if [ -n \"$RG\" ]; then U=\"%s/bystate/$RG?%s\"; else U=\"%s/bycountrycodeexact/$CC?%s\"; fi; "
            "curl -sf -m 15 -A SnapFE/1.0 \"$U\" > %s.t; "
            "[ -s %s.t ] || curl -sf -m 15 -A SnapFE/1.0 \"%s/bycountrycodeexact/$CC?%s\" > %s.t; "
            "[ -s %s.t ] && mv %s.t %s; rm -f %s.t %s ) &",
            RADIO_BUSY, RADIO_LOC_TMP,
            m1, P, m1, P,
            RADIO_LIST_TMP,
            RADIO_LIST_TMP, m2, P, RADIO_LIST_TMP,
            RADIO_LIST_TMP, RADIO_LIST_TMP, RADIO_LIST_TMP, RADIO_LIST_TMP, RADIO_BUSY);
    }
    system(cmd);
}
static void radio_poll(void) {
    if (radio_pid > 0) {
        int r = waitpid(radio_pid, NULL, WNOHANG);
        if (r == radio_pid || (r < 0 && errno == ECHILD)) {
            int fast = (SDL_GetTicks() - radio_started_at < 4000);
            radio_pid = 0; radio_playing_idx = -1; radio_now[0] = 0; radio_vol_dirty = 0;
            snprintf(radio_status, sizeof radio_status,
                     fast ? "That station won't play -- try another" : "Stream stopped");
        } else if (radio_now[0] && SDL_GetTicks() - radio_started_at > 3000 &&
                   strncmp(radio_status, "Connecting", 10) == 0) {
            snprintf(radio_status, sizeof radio_status, "Playing: %s", radio_now);
        }
        // Debounced volume change -> restart the stream at the new level.
        if (radio_vol_dirty && SDL_GetTicks() - radio_vol_at > 550) {
            int keep = radio_playing_idx;
            radio_vol_dirty = 0;
            if (keep >= 0) radio_play(keep);
        }
    } else {
        radio_vol_dirty = 0;
    }
    if (radio_loading && access(RADIO_BUSY, F_OK) != 0) {
        radio_loading = 0;
        radio_read_location();
        radio_parse();
    }
    if (radio_loading && SDL_GetTicks() - radio_fetch_started > 25000) {
        radio_loading = 0;
        snprintf(radio_status, sizeof radio_status, "Lookup timed out -- check Wi-Fi");
    }
}
#else
static void radio_stop(void) { radio_pid = 0; radio_now[0] = 0; radio_playing_idx = -1; }
static void game_audio_mute(int on, int aspect, int rotation) { (void)on; (void)aspect; (void)rotation; }
static void ra_user_settings_capture(void) {}
static void ra_hotkeys_capture(void) {}
static void ra_hotkeys_set_snap_fastforward(void) {}
static void ra_hotkeys_apply_to_cfg(const char *path) { (void)path; }
static void radio_play(int idx) { (void)idx; snprintf(radio_status, sizeof radio_status, "Radio runs on the device build"); }
static void radio_apply_volume(void) {}
static void radio_refresh(const char *s) { (void)s; snprintf(radio_status, sizeof radio_status, "Radio runs on the device build"); }
static void radio_poll(void) {}
#endif

// ===================================================================== //
//  Music player  --  local files from the SD card, played via mpv       //
// ===================================================================== //
// Reads .mp3 / .flac / .wav / .ogg / .m4a / .opus from  <userdata>/music
// (a folder Knulli already provisions). Playback is a detached mpv, same
// model as the radio, with a Unix-socket IPC channel for pause/resume.
#define MUSIC_MAX 600
#define MUSIC_IPC "/tmp/snapos-music.sock"
typedef struct { char path[1024]; char name[192]; } MusicTrack;
static MusicTrack music_tracks[MUSIC_MAX];
static int  music_count = 0;
static int  music_sel = 0;
static int  music_scanned = 0;
static int  music_playing = -1;      // index into music_tracks[], or -1
static int  music_pid = 0;
static int  music_paused = 0;
static int  music_user_stop = 0;     // set around a deliberate stop, to suppress auto-advance
static int  music_persist = 1;       // persisted: keep playing after you leave the Music screen
static int  music_over_games = 0;    // persisted: keep playing during a game (mutes the game)
static char music_status[128] = "";
void strip_ext(const char *filename, char *out, size_t outsize);  // defined later
// forward decls so the Now Playing home widget can show real cover art
SDL_Surface* load_cached_art_surface(const char *platform_dir, const char *title, int art_idx);
static void surface_opaque_bbox(SDL_Surface *s, unsigned char op[4]);
static SDL_Rect art_tight_rect(SDL_Rect fit, const unsigned char op[4]);
static SDL_Texture *make_silhouette_shadow(SDL_Renderer *ren, SDL_Surface *src);
static void draw_silhouette_shadow(SDL_Renderer *ren, SDL_Texture *shadow, SDL_Rect fit, SDL_Color tint);
static void draw_art_outline(SDL_Renderer *ren, SDL_Rect d);
static SDL_Color selection_shadow_color(void);
static SDL_Texture *tex_from_surface(SDL_Renderer *ren, SDL_Surface *s);
SDL_Rect fit_rect_for_texture(SDL_Texture *tex, SDL_Rect bounds);
void draw_soft_shadow(SDL_Renderer *ren, SDL_Rect img_rect, SDL_Color color);

static void music_dir(char *o, size_t n) {
#ifdef SNAPOS_TARGET_KNULLI
    snprintf(o, n, "%s/music", sn_userdata_root());
#else
    snprintf(o, n, "%s/music", sn_data_root());
#endif
}
static int music_is_audio(const char *nm) {
    const char *d = strrchr(nm, '.');
    if (!d) return 0;
    return !strcasecmp(d, ".mp3") || !strcasecmp(d, ".flac") || !strcasecmp(d, ".wav")
        || !strcasecmp(d, ".ogg") || !strcasecmp(d, ".m4a")  || !strcasecmp(d, ".opus");
}
static void music_scan_dir(const char *dir, int depth) {
    if (depth > 5 || music_count >= MUSIC_MAX) return;
    DIR *d = opendir(dir);
    if (!d) return;
    struct dirent *e;
    while ((e = readdir(d)) != NULL && music_count < MUSIC_MAX) {
        if (e->d_name[0] == '.') continue;
        char full[1024];
        snprintf(full, sizeof full, "%s/%s", dir, e->d_name);
        struct stat st;
        if (stat(full, &st) != 0) continue;
        if (S_ISDIR(st.st_mode)) music_scan_dir(full, depth + 1);
        else if (music_is_audio(e->d_name)) {
            snprintf(music_tracks[music_count].path, sizeof music_tracks[0].path, "%s", full);
            strip_ext(e->d_name, music_tracks[music_count].name, sizeof music_tracks[0].name);
            music_count++;
        }
    }
    closedir(d);
}
static int music_name_cmp(const void *a, const void *b) {
    return strcasecmp(((const MusicTrack *)a)->name, ((const MusicTrack *)b)->name);
}
static void music_scan(void) {
    music_count = 0;
    char dir[700];
    music_dir(dir, sizeof dir);
    mkdir(dir, 0755);
    music_scan_dir(dir, 0);
    qsort(music_tracks, music_count, sizeof music_tracks[0], music_name_cmp);
    music_scanned = 1;
    if (music_count) snprintf(music_status, sizeof music_status, "%d track%s", music_count, music_count == 1 ? "" : "s");
    else             snprintf(music_status, sizeof music_status, "No music found. Add files to %s", dir);
}
static void music_stop(void) {
    if (music_pid > 0) {
        kill(-music_pid, SIGTERM); kill(music_pid, SIGTERM);
        for (int i = 0; i < 10 && waitpid(music_pid, NULL, WNOHANG) == 0; i++) usleep(20000);
        kill(-music_pid, SIGKILL); waitpid(music_pid, NULL, WNOHANG);
    }
    music_pid = 0; music_playing = -1; music_paused = 0;
}
static void music_play(int idx) {
    if (idx < 0 || idx >= music_count) return;
    music_user_stop = 1; music_stop(); music_user_stop = 0;
    pid_t pid = fork();
    if (pid == 0) {
        setsid();
        int nul = open("/dev/null", O_RDWR);
        if (nul >= 0) { dup2(nul, 0); dup2(nul, 1); dup2(nul, 2); }
        setenv("XDG_RUNTIME_DIR", "/var/run", 1);
        execlp("mpv", "mpv", "--no-video", "--no-terminal", "--really-quiet",
               "--idle=no", "--volume=100", "--input-ipc-server=" MUSIC_IPC,
               "--", music_tracks[idx].path, (char *)NULL);
        execlp("ffplay", "ffplay", "-nodisp", "-autoexit", "-loglevel", "quiet",
               music_tracks[idx].path, (char *)NULL);
        _exit(127);
    }
    if (pid < 0) { snprintf(music_status, sizeof music_status, "Could not start player"); return; }
    music_pid = pid; music_playing = idx; music_paused = 0;
    snprintf(music_status, sizeof music_status, "Playing: %s", music_tracks[idx].name);
}
static void music_ipc(const char *cmd) {
    int fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (fd < 0) return;
    struct sockaddr_un a; memset(&a, 0, sizeof a);
    a.sun_family = AF_UNIX;
    snprintf(a.sun_path, sizeof a.sun_path, "%s", MUSIC_IPC);
    if (connect(fd, (struct sockaddr *)&a, sizeof a) == 0) {
        ssize_t _w = write(fd, cmd, strlen(cmd)); (void)_w;
    }
    close(fd);
}
static void music_toggle_pause(void) {
    if (music_pid <= 0) return;
    music_ipc("{\"command\":[\"cycle\",\"pause\"]}\n");
    music_paused = !music_paused;
    snprintf(music_status, sizeof music_status, "%s: %s",
             music_paused ? "Paused" : "Playing",
             music_playing >= 0 ? music_tracks[music_playing].name : "");
}
static void music_poll(void) {
    if (music_pid <= 0) return;
    int r = waitpid(music_pid, NULL, WNOHANG);
    if (r == music_pid || (r < 0 && errno == ECHILD)) {
        int was = music_playing;
        music_pid = 0; music_playing = -1; music_paused = 0;
        if (!music_user_stop && was >= 0 && was + 1 < music_count) music_play(was + 1);   // auto-advance
        else snprintf(music_status, sizeof music_status, "Stopped");
    }
}

// ===================================================================== //
//  First-time setup wizard                                              //
