// Button numbers are the raw SDL joystick indices for the Anbernic RG34XX-SP,
// per Knulli's own es_input.cfg: a=3 b=4 y=5 x=6 l1=7 r1=8 select=9 start=10
// hotkey=11 l2=13 r2=14, d-pad on hat 0.
static SDL_Keycode pad_map_joybutton(int b) {
    switch (b) {
        case 3:  return SDLK_RETURN;   // A -> confirm / launch
        case 10: return SDLK_F1;       // Start -> open Settings
        case 4:  return SDLK_ESCAPE;   // B -> back / cancel
        case 9:  return SDLK_SLASH;    // Select -> search (Game Library)
        case 16: return SDLK_UNKNOWN;  // Menu/Fn is handled as a SNAP gesture before mapping
        case 5:  return SDLK_f;        // Y -> favorite toggle
        case 6:  return SDLK_s;        // X -> cycle sort (Game Library)
        case 7:  return SDLK_q;        // L1 -> scroll / step through content (lists, blurb, tracks)
        case 8:  return SDLK_e;        // R1 -> scroll / step through content
        case 13: return SDLK_PAGEUP;   // L2 -> previous view / settings tab
        case 14: return SDLK_PAGEDOWN; // R2 -> next     view / settings tab
        default: return SDLK_UNKNOWN;
    }
}

// Commit the on-screen keyboard buffer to wherever it was opened for.
static void kb_commit(SDL_Renderer *ren, TTF_Font *font_label, int *psel) {
    switch (kb_purpose) {
        case KB_PURPOSE_API_KEY:  save_api_key_from_buffer(); break;
        case KB_PURPOSE_RA_USER:
            snprintf(ra_username, sizeof ra_username, "%.63s", kb_buffer);
            save_ra_config();
            if (ra_username[0] && ra_token[0]) run_ra_check(0);
            break;
        case KB_PURPOSE_RA_TOKEN:
            snprintf(ra_token, sizeof ra_token, "%.95s", kb_buffer);
            save_ra_config();
            if (ra_username[0] && ra_token[0]) run_ra_check(0);
            break;
        case KB_PURPOSE_RA_WEB_KEY: snprintf(ra_web_api_key, sizeof ra_web_api_key, "%.95s", kb_buffer);
                                    save_ra_config(); break;
        case KB_PURPOSE_LIBRARY_SEARCH:
            snprintf(library_search, sizeof library_search, "%.63s", kb_buffer);
            rescan_active_games(ren, font_label);
            if (psel) *psel = 0;
            last_rendered_page_start = -1;
            break;
        case KB_PURPOSE_WIFI_PSK: wifi_connect(wifi_target_ssid, kb_buffer); break;
        case KB_PURPOSE_SS_USER:  snprintf(ss_user, sizeof ss_user, "%.63s", kb_buffer); save_ss_config(); break;
        case KB_PURPOSE_SS_PASS:  snprintf(ss_pass, sizeof ss_pass, "%.63s", kb_buffer); save_ss_config(); break;
        case KB_PURPOSE_LINK_IP:  if (kb_buffer[0]) link_join(kb_buffer); break;
        case KB_PURPOSE_WEATHER_LOC:
            snprintf(weather_loc, sizeof weather_loc, "%.63s", kb_buffer);
            g_weather_kicked = 0; g_weather_str[0] = '\0'; g_weather_mtime = 0; g_weather_at = 0;
            weather_kick(1);
            break;
        case KB_PURPOSE_PLAYER_NAME:
            snprintf(player_name, sizeof player_name, "%.31s", kb_buffer);
            break;
        case KB_PURPOSE_BT_PASSKEY:    bt_agent_answer_code(kb_buffer); break;
        case KB_PURPOSE_RADIO_SEARCH:  if (kb_buffer[0]) radio_refresh(kb_buffer); break;
        case KB_PURPOSE_BG_SEARCH:
            if (kb_buffer[0]) {
                snprintf(bg_online_query, sizeof bg_online_query, "%.95s", kb_buffer);
                bg_online_search_pending = 1;
                kb_return_state = STATE_BG_ONLINE;
            }
            break;
        case KB_PURPOSE_WALLHAVEN_KEY:
            save_wallhaven_key_from_buffer();
            break;
        case KB_PURPOSE_BG_RENAME:
            rename_selected_background();
            break;
        case KB_PURPOSE_CALENDAR_REMINDER: {
            if (kb_buffer[0]) {
                snprintf(calendar_reminder_pending_text,
                         sizeof calendar_reminder_pending_text, "%.159s", kb_buffer);
                // The keyboard returns to Calendar, where this controller-first
                // picker completes the reminder without requiring time typing.
                calendar_reminder_time_picker = 1;
            }
            break;
        }
        default: break;   // KB_PURPOSE_PRACTICE
    }
    kb_shift = 0;
}

// ===================================================================== //
//  "App Focused" home layout -- a grid of tappable tiles                //
// ===================================================================== //
// Icons: assets/icons/home/<slug>.{png,jpg,jpeg}  (any of the three).
// The resume tile and favourite tiles show the game's real cover art.
#define HOME_GRID_COLS 4
#define HOME_GRID_ROWS 2
#define HOME_GRID_PAGE_SIZE (HOME_GRID_COLS * HOME_GRID_ROWS)
static const char *HGRID_SLUGS[] =
    { "consoles","library","favorites","radio","music","retroarch","link","settings","surprise","resume","flashlight","minigames","achievements","calculator" };
#define HGRID_SLUG_N ((int)(sizeof(HGRID_SLUGS)/sizeof(HGRID_SLUGS[0])))
static SDL_Texture *hgrid_icon_cache[HGRID_SLUG_N] = { 0 };
static int          hgrid_icon_tried[HGRID_SLUG_N] = { 0 };

static SDL_Texture *hgrid_icon(SDL_Renderer *ren, const char *slug) {
    static unsigned icon_epoch = 0;
    if (icon_epoch != renderer_epoch) {
        memset(hgrid_icon_cache, 0, sizeof hgrid_icon_cache);
        memset(hgrid_icon_tried, 0, sizeof hgrid_icon_tried);
        icon_epoch = renderer_epoch;
    }
    for (int i = 0; i < HGRID_SLUG_N; i++) if (strcmp(HGRID_SLUGS[i], slug) == 0) {
        if (!hgrid_icon_tried[i]) {
            hgrid_icon_tried[i] = 1;
            char stem[600];
            snprintf(stem, sizeof stem, "%s/assets/icons/home/%s", sn_data_root(), slug);
            hgrid_icon_cache[i] = try_load_img(ren, stem, 512);
        }
        return hgrid_icon_cache[i];
    }
    return NULL;
}

// small cover-art cache for the resume / favourite tiles (load_cached_art
// builds a fresh texture each call, so we must not call it every frame)
#define HGRID_ART_CAP 12
static struct { char key[288]; SDL_Texture *tex; } hgrid_art[HGRID_ART_CAP];
static int hgrid_art_n = 0;
static SDL_Texture *hgrid_cover(SDL_Renderer *ren, const char *pdir, const char *path) {
    static unsigned art_epoch = 0;
    if (art_epoch != renderer_epoch) {
        memset(hgrid_art, 0, sizeof hgrid_art);
        hgrid_art_n = 0;
        art_epoch = renderer_epoch;
    }
    char raw[200]; const char *b = strrchr(path, '/');
    strip_ext(b ? b + 1 : path, raw, sizeof raw);
    char key[288]; snprintf(key, sizeof key, "%s|%s", pdir, raw);
    for (int i = 0; i < hgrid_art_n; i++) if (strcmp(hgrid_art[i].key, key) == 0) return hgrid_art[i].tex;
    if (hgrid_art_n >= HGRID_ART_CAP) {
        if (hgrid_art[0].tex) SDL_DestroyTexture(hgrid_art[0].tex);
        memmove(hgrid_art, hgrid_art + 1, sizeof(hgrid_art[0]) * (HGRID_ART_CAP - 1));
        hgrid_art_n = HGRID_ART_CAP - 1;
    }
    SDL_Texture *t = load_cached_art(ren, pdir, raw);   // may be NULL -> caller falls back
    snprintf(hgrid_art[hgrid_art_n].key, sizeof hgrid_art[0].key, "%s", key);
    hgrid_art[hgrid_art_n].tex = t;
    hgrid_art_n++;
    return t;
}

// Flatten the home rows into tile indices (everything except the WELCOME row).
static int hgrid_tiles(int *rt, int rcount, int *out) {
    int n = 0;
    // Resume is contextual rather than an app, so it remains pinned first.
    for (int i = 0; i < rcount && n < MAX_HOME_ROWS; i++)
        if (rt[i] == ROW_H_CONTINUE) out[n++] = i;
    // All actual launch tiles follow the user's persistent phone-style order.
    for (int oi = 0; oi < HOME_ORDER_COUNT && n < MAX_HOME_ROWS; oi++)
        for (int i = 0; i < rcount; i++)
            if (home_tile_key(rt[i]) == home_tile_order[oi]) { out[n++] = i; break; }
    // Keep any future tile types reachable even before an order migration.
    for (int i = 0; i < rcount && n < MAX_HOME_ROWS; i++) {
        if (rt[i] == ROW_H_WELCOME || rt[i] == ROW_H_CONTINUE || rt[i] == ROW_H_APP_WIDGET) continue;
        int already = 0; for (int k = 0; k < n; k++) if (out[k] == i) { already = 1; break; }
        if (!already) out[n++] = i;
    }
    return n;
}

typedef struct { int row_index, slot, span; } HGridItem;

static int hgrid_widget_slot_normalize(int slot) {
    if (slot < 0) slot = 0;
    // A two-wide widget may begin in columns 0, 1 or 2, never across a row.
    if (slot % HOME_GRID_COLS == HOME_GRID_COLS - 1) slot--;
    return slot;
}

// Lay apps into physical 4x2 page cells. The widget consumes two adjacent
// cells and apps naturally flow around it, so nothing is hidden underneath.
static int hgrid_layout(int *rt, int rcount, HGridItem *items, int *total_slots) {
    int base[MAX_HOME_ROWS], bn = hgrid_tiles(rt, rcount, base);
    int widget_row = -1;
    for (int i = 0; i < rcount; i++) if (rt[i] == ROW_H_APP_WIDGET) { widget_row = i; break; }

    int anchor = hgrid_widget_slot_normalize(app_widget_slot);
    if (anchor > bn) anchor = hgrid_widget_slot_normalize(bn);
    int n = 0, bi = 0, slot = 0, placed = widget_row < 0;
    while ((bi < bn || !placed) && n < MAX_HOME_ROWS) {
        if (!placed && (slot >= anchor || bi >= bn)) {
            if (slot < anchor) slot = anchor;
            slot = hgrid_widget_slot_normalize(slot);
            items[n++] = (HGridItem){ widget_row, slot, 2 };
            slot += 2;
            placed = 1;
        } else if (bi < bn) {
            items[n++] = (HGridItem){ base[bi++], slot++, 1 };
        }
    }
    *total_slots = slot;
    return n;
}

static int hgrid_layout_row_at(const HGridItem *items, int n, int cell) {
    for (int i = 0; i < n; i++)
        if (cell >= items[i].slot && cell < items[i].slot + items[i].span)
            return items[i].row_index;
    return -1;
}

static int hgrid_layout_nearest(const HGridItem *items, int n, int first, int last, int wanted) {
    int best = -1, best_d = 9999;
    for (int c = first; c <= last; c++) {
        int row = hgrid_layout_row_at(items, n, c);
        if (row < 0) continue;
        int d = c > wanted ? c - wanted : wanted - c;
        if (d < best_d) { best = row; best_d = d; }
    }
    return best;
}

static int hgrid_nav_layout(int *rt, int rcount, int current, SDL_Keycode key) {
    HGridItem items[MAX_HOME_ROWS]; int slots = 0;
    int n = hgrid_layout(rt, rcount, items, &slots);
    if (n <= 0) return current;
    int ci = 0;
    for (int i = 0; i < n; i++) if (items[i].row_index == current) { ci = i; break; }
    int page_count = (slots + HOME_GRID_PAGE_SIZE - 1) / HOME_GRID_PAGE_SIZE;
    if (page_count < 1) page_count = 1;
    int slot = items[ci].slot, span = items[ci].span;
    int page = slot / HOME_GRID_PAGE_SIZE;
    int local = slot % HOME_GRID_PAGE_SIZE;
    int row = local / HOME_GRID_COLS, col = local % HOME_GRID_COLS;
    int target = -1;

    if (key == SDLK_e || key == SDLK_q) { // R1 / L1: explicit page movement
        int np = (page + (key == SDLK_e ? 1 : -1) + page_count) % page_count;
        int wanted = np * HOME_GRID_PAGE_SIZE + local;
        target = hgrid_layout_row_at(items, n, wanted);
        if (target < 0)
            target = hgrid_layout_nearest(items, n, np * HOME_GRID_PAGE_SIZE,
                                          np * HOME_GRID_PAGE_SIZE + HOME_GRID_PAGE_SIZE - 1, wanted);
    } else if (key == SDLK_RIGHT) {
        int end_local = local + span - 1;
        int wanted = (end_local % HOME_GRID_COLS < HOME_GRID_COLS - 1)
                   ? slot + span
                   : (page + 1) * HOME_GRID_PAGE_SIZE + row * HOME_GRID_COLS;
        target = hgrid_layout_row_at(items, n, wanted);
    } else if (key == SDLK_LEFT) {
        int wanted = col > 0 ? slot - 1
                   : (page > 0 ? (page - 1) * HOME_GRID_PAGE_SIZE + row * HOME_GRID_COLS + HOME_GRID_COLS - 1 : -1);
        if (wanted >= 0) target = hgrid_layout_row_at(items, n, wanted);
    } else if (key == SDLK_DOWN || key == SDLK_UP) {
        int wanted = slot + (key == SDLK_DOWN ? HOME_GRID_COLS : -HOME_GRID_COLS);
        if (wanted >= 0) {
            target = hgrid_layout_row_at(items, n, wanted);
            if (target < 0) {
                int tp = wanted / HOME_GRID_PAGE_SIZE;
                int tr = (wanted % HOME_GRID_PAGE_SIZE) / HOME_GRID_COLS;
                target = hgrid_layout_nearest(items, n,
                    tp * HOME_GRID_PAGE_SIZE + tr * HOME_GRID_COLS,
                    tp * HOME_GRID_PAGE_SIZE + tr * HOME_GRID_COLS + HOME_GRID_COLS - 1, wanted);
            }
        }
    }
    return target >= 0 ? target : current;
}

static void hgrid_widget_move(int *rt, int rcount, SDL_Keycode key) {
    int base[MAX_HOME_ROWS], bn = hgrid_tiles(rt, rcount, base);
    int s = hgrid_widget_slot_normalize(app_widget_slot);
    if (key == SDLK_LEFT)       s = (s % HOME_GRID_COLS > 0) ? s - 1 : (s >= 2 ? s - 2 : s);
    else if (key == SDLK_RIGHT) s = (s % HOME_GRID_COLS < 2) ? s + 1 : s + 2;
    else if (key == SDLK_UP)    s -= HOME_GRID_COLS;
    else if (key == SDLK_DOWN)  s += HOME_GRID_COLS;
    if (s < 0) s = 0;
    if (s > bn) s = bn;
    app_widget_slot = hgrid_widget_slot_normalize(s);
}

static void hgrid_reorder_move(int *rt, int rcount, SDL_Keycode key) {
    int from_key = (home_selected >= 0 && home_selected < rcount)
                 ? home_tile_key(rt[home_selected]) : -1;
    if (from_key < 0) return;

    // Follow the actual physical 4x2 layout rather than the underlying app
    // array. The old ordinal movement ignored the two-cell widget, so Up/Down
    // could swap with a visually diagonal app. If the next physical item is
    // the widget, step across it once in the same requested direction.
    int probe = home_selected, target = -1;
    for (int step = 0; step < 3; step++) {
        int next = hgrid_nav_layout(rt, rcount, probe, key);
        if (next == probe) break;
        probe = next;
        if (probe < 0 || probe >= rcount) break;
        if (home_tile_key(rt[probe]) >= 0) { target = probe; break; }
        if (rt[probe] != ROW_H_APP_WIDGET) break; // Resume remains pinned.
    }
    if (target < 0) return;

    int a = from_key, b = home_tile_key(rt[target]);
    int ai = -1, bi = -1;
    for (int i = 0; i < HOME_ORDER_COUNT; i++) {
        if (home_tile_order[i] == a) ai = i;
        if (home_tile_order[i] == b) bi = i;
    }
    if (ai < 0 || bi < 0) return;
    home_tile_order[ai] = b;
    home_tile_order[bi] = a;
    home_grid_reorder_dirty = 1;
    play_click();
}

static void draw_simple_home_icon(SDL_Renderer *ren, SDL_Rect box, const char *slug) {
    int dark = themes[theme_idx].bg.r + themes[theme_idx].bg.g + themes[theme_idx].bg.b < 360;
    SDL_Color paper = dark ? (SDL_Color){245,245,245,255} : (SDL_Color){20,20,20,255};
    SDL_Color ink   = dark ? (SDL_Color){20,20,20,255} : (SDL_Color){250,250,250,255};
    SDL_Rect badge = { box.x + box.w/4, box.y + box.h/4, box.w/2, box.h/2 };
    fill_rounded(ren, badge, 10, paper.r, paper.g, paper.b, 255);
    const char *mark = "AP";
    if (!strcmp(slug,"consoles")) mark="C"; else if (!strcmp(slug,"library")) mark="G";
    else if (!strcmp(slug,"favorites")) mark="F"; else if (!strcmp(slug,"radio")) mark="R";
    else if (!strcmp(slug,"music")) mark="M"; else if (!strcmp(slug,"retroarch")) mark="RA";
    else if (!strcmp(slug,"link")) mark="L"; else if (!strcmp(slug,"settings")) mark="S";
    else if (!strcmp(slug,"surprise")) mark="?"; else if (!strcmp(slug,"flashlight")) mark="FL";
    else if (!strcmp(slug,"minigames")) mark="MG"; else if (!strcmp(slug,"achievements")) mark="A";
    else if (!strcmp(slug,"calculator")) mark="123";
    else if (!strcmp(slug,"resume")) mark=">";
    SDL_Texture *mt = render_text(ren, font_fixed ? font_fixed : font_label, mark, ink);
    if (mt) { int mw,mh; SDL_QueryTexture(mt,NULL,NULL,&mw,&mh); SDL_RenderCopy(ren,mt,NULL,&(SDL_Rect){badge.x+badge.w/2-mw/2,badge.y+badge.h/2-mh/2,mw,mh}); }
}

static void draw_app_grid_widget(SDL_Renderer *ren, Theme *th, SDL_Rect box, int selected) {
    if (selected) {
        fill_rounded(ren, (SDL_Rect){ box.x - 4, box.y - 4, box.w + 8, box.h + 8 }, 14,
                     th->accent2.r, th->accent2.g, th->accent2.b, 245);
    }
    fill_rounded(ren, box, 11, th->select_bg.r, th->select_bg.g, th->select_bg.b, 225);
    SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 230);
    SDL_RenderDrawRect(ren, &box);
    SDL_RenderSetClipRect(ren, &box);

    int x = box.x + 12, y = box.y + 9, w = box.w - 24;
    const char *title = app_widget_names[(app_widget_kind >= 0 && app_widget_kind < APP_WIDGET_COUNT) ? app_widget_kind : 0];
    SDL_Texture *ht = render_text(ren, font_label_bold ? font_label_bold : font_label, title, th->accent2);
    int hw, hh; SDL_QueryTexture(ht, NULL, NULL, &hw, &hh);
    SDL_RenderCopy(ren, ht, NULL, &(SDL_Rect){ x, y, hw, hh });
    y += hh + 5;

    if (app_widget_kind == APP_WIDGET_CLOCK) {
        time_t now = time(NULL); struct tm *lt = localtime(&now);
        char big[24], sub[64];
        strftime(big, sizeof big, clock_24h ? "%H:%M" : "%I:%M", lt);
        if (!clock_24h && big[0] == '0') memmove(big, big + 1, strlen(big));
        strftime(sub, sizeof sub, clock_24h ? "%A, %B %d" : "%p  -  %A, %B %d", lt);
        SDL_Texture *bt = render_text_fit(ren, font_big, big, g_ui_text, w);
        int bw,bh; SDL_QueryTexture(bt,NULL,NULL,&bw,&bh);
        SDL_RenderCopy(ren,bt,NULL,&(SDL_Rect){x,y,bw,bh}); y += bh + 2;
        SDL_Texture *st = render_text_fit(ren,font_label,sub,g_ui_dim,w);
        int sw,sh; SDL_QueryTexture(st,NULL,NULL,&sw,&sh);
        SDL_RenderCopy(ren,st,NULL,&(SDL_Rect){x,y,sw,sh});
    } else if (app_widget_kind == APP_WIDGET_WEATHER) {
        weather_read(); weather_kick(0);
        char temp[32] = "--", cond[120] = "Fetching local weather...";
        if (g_weather_str[0]) {
            const char *sp = strchr(g_weather_str, ' ');
            snprintf(temp, sizeof temp, "%.*s", sp ? (int)(sp - g_weather_str) : (int)strlen(g_weather_str), g_weather_str);
            snprintf(cond, sizeof cond, "%s", (sp && sp[1]) ? sp + 1 : "Current conditions");
        }
        int wk = weather_icon_kind(cond);
        if (wk == WX_SUN && weather_is_night()) wk = WX_CLEARNIGHT;
        int isz = 48;
        if (wk != WX_NONE) draw_weather_icon(ren, x, y, isz, wk, g_ui_text, th->bg);
        SDL_Texture *bt = render_text(ren,font_big,temp,g_ui_text);
        int bw,bh; SDL_QueryTexture(bt,NULL,NULL,&bw,&bh);
        SDL_RenderCopy(ren,bt,NULL,&(SDL_Rect){x+(wk!=WX_NONE?isz+10:0),y,bw,bh});
        y += (bh > isz ? bh : isz) + 2;
        SDL_Texture *ct = render_text_fit(ren,font_label,cond,g_ui_dim,w);
        int cw,ch; SDL_QueryTexture(ct,NULL,NULL,&cw,&ch);
        SDL_RenderCopy(ren,ct,NULL,&(SDL_Rect){x,y,cw,ch});
        y += ch + 2;
        const char *refresh = SDL_GetTicks() < g_weather_refresh_msg_until ? "Refreshing..." : "A  Refresh";
        SDL_Texture *rt = render_text(ren, font_label, refresh, th->accent2);
        int rw, rh; SDL_QueryTexture(rt, NULL, NULL, &rw, &rh);
        // Pin this control to the card's lower-right corner. Large fonts can
        // consume the natural content flow, but the action must remain visible
        // without escaping into the app-label/footer band.
        SDL_RenderCopy(ren, rt, NULL,
                       &(SDL_Rect){ box.x + box.w - rw - 10, box.y + box.h - rh - 7, rw, rh });
    } else if (app_widget_kind == APP_WIDGET_BATTERY) {
        int pct, charging; read_battery(&pct, &charging);
        char big[32], sub[100];
        if (pct >= 0) snprintf(big, sizeof big, "%d%%", pct);
        else snprintf(big, sizeof big, "--");
        battery_details_text(sub, sizeof sub, charging);
        SDL_Texture *bt = render_text(ren,font_big,big,g_ui_text);
        int bw,bh; SDL_QueryTexture(bt,NULL,NULL,&bw,&bh);
        SDL_RenderCopy(ren,bt,NULL,&(SDL_Rect){x,y,bw,bh});
        draw_battery_glyph(ren, x + bw + 18, y + bh/2 - 12, 24, pct, th->accent2);
        y += bh + 2;
        SDL_Texture *st = render_text_fit(ren,font_label,sub,g_ui_dim,w);
        int sw,sh; SDL_QueryTexture(st,NULL,NULL,&sw,&sh);
        SDL_RenderCopy(ren,st,NULL,&(SDL_Rect){x,y,sw,sh});
    } else if (app_widget_kind == APP_WIDGET_CALENDAR) {
        char range[72]; calendar_week_range_short(range, sizeof range);
        SDL_Texture *mt = render_text_fit(ren, font_label, range, g_ui_dim, w);
        int mw, mh; SDL_QueryTexture(mt, NULL, NULL, &mw, &mh);
        SDL_RenderCopy(ren, mt, NULL, &(SDL_Rect){ x, y, mw, mh });
        int strip_y = y + mh + 5;
        int strip_h = box.y + box.h - strip_y - TTF_FontHeight(font_label) - 10;
        draw_calendar_week_strip(ren, th, x, strip_y, w, strip_h);
        SDL_Texture *open = render_text(ren, font_label, "A  Open", th->accent2);
        int ow, oh; SDL_QueryTexture(open, NULL, NULL, &ow, &oh);
        SDL_RenderCopy(ren, open, NULL,
                       &(SDL_Rect){ box.x + box.w - ow - 10, box.y + box.h - oh - 7, ow, oh });
    }
    SDL_RenderSetClipRect(ren, NULL);
}

static void render_home_grid(SDL_Renderer *ren, Theme *th, int *rt, int *rx, int rcount) {
    HGridItem items[MAX_HOME_ROWS]; int total_slots = 0;
    int n = hgrid_layout(rt, rcount, items, &total_slots);
    if (n == 0) {
        SDL_Texture *m = render_text(ren, font_small, "No games yet -- add ROMs to your games card", g_ui_dim);
        int w, h; SDL_QueryTexture(m, NULL, NULL, &w, &h);
        SDL_RenderCopy(ren, m, NULL, &(SDL_Rect){ WIN_W/2 - w/2, WIN_H/2 - h/2, w, h });
        return;
    }
    if (home_selected < 0 || home_selected >= rcount || rt[home_selected] == ROW_H_WELCOME)
        home_selected = items[0].row_index;
    int selected_item = 0;
    for (int k = 0; k < n; k++) if (items[k].row_index == home_selected) { selected_item = k; break; }
    const int cols = HOME_GRID_COLS;
    const int rows = HOME_GRID_ROWS;
    int page_count = (total_slots + HOME_GRID_PAGE_SIZE - 1) / HOME_GRID_PAGE_SIZE;
    if (page_count < 1) page_count = 1;
    const int page = items[selected_item].slot / HOME_GRID_PAGE_SIZE;
    int mode_banner = home_grid_reorder || app_widget_moving;
    int top = HUD_BAR_H + (mode_banner ? 29 : 8), gap = 10;
    // App titles follow the user's font family, size and legibility choices.
    // Width fitting below keeps even X-Large labels inside their own cells.
    TTF_Font *grid_label_font = font_label_bold ? font_label_bold : font_label;
    int label_h = TTF_FontHeight(grid_label_font) + 4;
    // Keep controls and page dots in their own footer. Previously the grid
    // consumed this band, so the second-row labels, help and dots shared the
    // same pixels on the 720x480 panel.
    const int footer_h = 38;
    int available_h = WIN_H - top - footer_h - (rows - 1) * gap - rows * (label_h + 4);
    int tile_by_h = rows > 0 ? available_h / rows : 100;
    int tile_by_w = (WIN_W - 36 - (cols - 1) * gap) / cols;
    int tile = tile_by_h < tile_by_w ? tile_by_h : tile_by_w;
    if (tile > 164) tile = 164;
    if (tile < 72) tile = 72;
    int cell_h = tile + label_h + 4 + gap;
    int grid_w = cols * tile + (cols - 1) * gap;
    int mx = (WIN_W - grid_w) / 2;

    if (mode_banner) {
        const char *msg = app_widget_moving ? "MOVING WIDGET  -  D-pad Place   A Confirm   B Cancel"
                        : home_grid_dragging ? "MOVING APP  -  D-pad Place   A Confirm   B Cancel"
                        : "EDIT APPS  -  D-pad Choose   Y Pick Up   B Done";
        SDL_Texture *mh = render_text_fit(ren, font_label, msg, th->accent2, WIN_W - 40);
        int mw, mhh; SDL_QueryTexture(mh, NULL, NULL, &mw, &mhh);
        SDL_RenderCopy(ren, mh, NULL, &(SDL_Rect){ WIN_W/2 - mw/2, HUD_BAR_H + 3, mw, mhh });
        g_text_scrolling = 1;
    }

    for (int k = 0; k < n; k++) {
        if (items[k].slot / HOME_GRID_PAGE_SIZE != page) continue;
        int local = items[k].slot % HOME_GRID_PAGE_SIZE;
        int r = local / cols, c = local % cols;
        int i = items[k].row_index, trt = rt[i], is_sel = (i == home_selected);
        int jiggle_x = 0, jiggle_y = 0;
        if (home_grid_reorder && home_tile_key(trt) >= 0) {
            float phase = (float)SDL_GetTicks() * 0.018f + (float)k * 1.7f;
            jiggle_x = (int)(sinf(phase) * 2.0f);
            jiggle_y = (int)(cosf(phase * 0.83f) * 2.0f);
        }
        int cx = mx + c * (tile + gap) + jiggle_x;
        int cy = top + r * cell_h + jiggle_y;
        SDL_Rect box = { cx, cy, items[k].span == 2 ? tile * 2 + gap : tile, tile };

        if (trt == ROW_H_APP_WIDGET) {
            draw_app_grid_widget(ren, th, box, is_sel);
            continue;
        }

        SDL_Texture *art = NULL; const char *slug = NULL; char label[96] = "";
        if (trt == ROW_H_CONTINUE) {
            ActivityRecord *ar = &activity_records[rx[i]];
            art = hgrid_cover(ren, ar->platform_dir, ar->path);
            if (!art) slug = "resume";
            snprintf(label, sizeof label, "%s", ar->title);
        } else if (trt == ROW_H_FAV_ITEM) {
            FavoriteEntry *fv = &favorites[rx[i]];
            art = hgrid_cover(ren, fv->platform_dir, fv->path);
            snprintf(label, sizeof label, "%s", fv->title);
        } else if (trt == ROW_H_QUICK_CONSOLES) { slug = "consoles";  snprintf(label, sizeof label, "Consoles"); }
        else if (trt == ROW_H_QUICK_LIBRARY)    { slug = "library";   snprintf(label, sizeof label, "Library"); }
        else if (trt == ROW_H_QUICK_FAVORITES)  { slug = "favorites"; snprintf(label, sizeof label, "Favorites"); }
        else if (trt == ROW_H_QUICK_RADIO)      { slug = "radio";     snprintf(label, sizeof label, radio_now[0] ? "Radio *" : "Radio"); }
        else if (trt == ROW_H_QUICK_MUSIC)      { slug = "music";     snprintf(label, sizeof label, music_playing >= 0 ? "Music *" : "Music"); }
        else if (trt == ROW_H_QUICK_RETROARCH)  { slug = "retroarch"; snprintf(label, sizeof label, "RetroArch"); }
        else if (trt == ROW_H_QUICK_LINK)       { slug = "link";      snprintf(label, sizeof label, "Link Play"); }
        else if (trt == ROW_H_QUICK_SETTINGS)   { slug = "settings";  snprintf(label, sizeof label, "Settings"); }
        else if (trt == ROW_H_QUICK_FLASHLIGHT) { slug = "flashlight"; snprintf(label, sizeof label, "Flashlight"); }
        else if (trt == ROW_H_QUICK_MINIGAMES)  { slug = "minigames"; snprintf(label, sizeof label, "Mini Games"); }
        else if (trt == ROW_H_QUICK_ACHIEVEMENTS) { slug = "achievements"; snprintf(label, sizeof label, "Achievements"); }
        else if (trt == ROW_H_QUICK_CALCULATOR) { slug = "calculator"; snprintf(label, sizeof label, "Calculator"); }
        else if (trt == ROW_H_SURPRISE)         { slug = "surprise";  snprintf(label, sizeof label, "Surprise Me"); }
        if (art) {
            if (is_sel)
                fill_rounded(ren, (SDL_Rect){ box.x - 4, box.y - 4, box.w + 8, box.h + 8 }, 14,
                             th->accent2.r, th->accent2.g, th->accent2.b, 235);
            fill_rounded(ren, box, 10, th->select_bg.r, th->select_bg.g, th->select_bg.b, 165);
            SDL_Rect d = fit_rect_for_texture(art, (SDL_Rect){ box.x + 7, box.y + 7, box.w - 14, box.h - 14 });
            SDL_RenderCopy(ren, art, NULL, &d);
        } else if (slug) {
            SDL_Texture *icon = hgrid_icon(ren, slug);
            if (icon) {
                // Home icons are transparent artwork. Supply the rounded tile
                // in code so it follows every active colour theme instead of
                // baking one fixed background into the PNG. The only border is
                // the tight three-pixel focus outline requested for navigation.
                if (is_sel)
                    fill_rounded(ren, (SDL_Rect){ box.x - 3, box.y - 3, box.w + 6, box.h + 6 }, 14,
                                 th->accent2.r, th->accent2.g, th->accent2.b, 245);
                fill_rounded(ren, box, 12,
                             th->select_bg.r, th->select_bg.g, th->select_bg.b, 255);
                SDL_Rect d = fit_rect_for_texture(icon,
                    (SDL_Rect){ box.x + 9, box.y + 9, box.w - 18, box.h - 18 });
                SDL_RenderCopy(ren, icon, NULL, &d);
            } else {
                if (is_sel)
                    fill_rounded(ren, (SDL_Rect){ box.x - 3, box.y - 3, box.w + 6, box.h + 6 }, 13,
                                 th->accent2.r, th->accent2.g, th->accent2.b, 245);
                draw_simple_home_icon(ren, box, slug);
            }
        }

        SDL_Texture *lt = render_text_fit(ren, grid_label_font, label, is_sel ? g_ui_text : g_ui_dim, box.w + 10);
        int lw, lh; SDL_QueryTexture(lt, NULL, NULL, &lw, &lh);
        SDL_RenderCopy(ren, lt, NULL, &(SDL_Rect){ cx + box.w/2 - lw/2, cy + tile + 5, lw, lh });
    }

    // Small page dots make the extra app screens discoverable without taking
    // space away from the fixed 4x2 grid.
    if (page_count > 1) {
        int dot = 7, dg = 9, total = page_count * dot + (page_count - 1) * dg;
        int dx = WIN_W / 2 - total / 2, dy = WIN_H - 15;
        for (int p = 0; p < page_count; p++) {
            SDL_Color dc = (p == page) ? th->accent2 : th->dim;
            fill_rounded(ren, (SDL_Rect){ dx + p * (dot + dg), dy, dot, dot }, dot/2,
                         dc.r, dc.g, dc.b, p == page ? 255 : 150);
        }
    }

    if (!home_grid_reorder && !app_widget_moving) {
        // Weather advertises A Refresh inside its card; repeating it here made
        // the footer unnecessarily long and crowded the centered page dots.
        SDL_Texture *xh = render_text(ren, font_label, "X  Widget", g_ui_dim);
        SDL_Texture *yh = render_text(ren, font_label, "Y  Move", g_ui_dim);
        int xw,xhgt,yw,yhgt; SDL_QueryTexture(xh,NULL,NULL,&xw,&xhgt); SDL_QueryTexture(yh,NULL,NULL,&yw,&yhgt);
        int fy = WIN_H - (xhgt > yhgt ? xhgt : yhgt) - 8;
        SDL_RenderCopy(ren,xh,NULL,&(SDL_Rect){14,fy,xw,xhgt});
        SDL_RenderCopy(ren,yh,NULL,&(SDL_Rect){24+xw,fy,yw,yhgt});
    }

    if (app_widget_picker) {
        SDL_SetRenderDrawColor(ren, 0, 0, 0, 190);
        SDL_RenderFillRect(ren, &(SDL_Rect){0,0,WIN_W,WIN_H});
        int existing = app_widget_kind != APP_WIDGET_NONE;
        int count = existing ? 5 : 4;
        int bw = WIN_W > 680 ? 420 : WIN_W - 100;
        int pitch = TTF_FontHeight(font_label) + 9;
        int bh = 62 + count * pitch + 34;
        int bx = WIN_W/2 - bw/2, by = WIN_H/2 - bh/2;
        fill_rounded(ren, (SDL_Rect){bx,by,bw,bh}, 14, th->bg.r,th->bg.g,th->bg.b,255);
        SDL_SetRenderDrawColor(ren,th->accent2.r,th->accent2.g,th->accent2.b,255);
        SDL_RenderDrawRect(ren,&(SDL_Rect){bx,by,bw,bh});
        SDL_Texture *pt=render_text(ren,font_small_bold,existing?"APP WIDGET":"ADD APP WIDGET",th->accent2);
        int pw,ph; SDL_QueryTexture(pt,NULL,NULL,&pw,&ph);
        SDL_RenderCopy(ren,pt,NULL,&(SDL_Rect){bx+20,by+16,pw,ph});
        int py=by+48;
        for(int j=0;j<count;j++) {
            const char *name = j < 4 ? app_widget_names[j+1] : "Remove Widget";
            int sel = app_widget_picker_sel == j;
            if(sel) fill_rounded(ren,(SDL_Rect){bx+12,py-3,bw-24,pitch-1},8,
                                  th->select_bg.r,th->select_bg.g,th->select_bg.b,255);
            SDL_Texture *ot=render_text(ren,font_label,name,sel?g_ui_text:g_ui_dim);
            int ow,oh; SDL_QueryTexture(ot,NULL,NULL,&ow,&oh);
            SDL_RenderCopy(ren,ot,NULL,&(SDL_Rect){bx+24,py,ow,oh});
            py += pitch;
        }
        SDL_Texture *ft=render_text(ren,font_label,"A  Choose     B  Cancel",g_ui_dim);
        int fw,fh; SDL_QueryTexture(ft,NULL,NULL,&fw,&fh);
        SDL_RenderCopy(ren,ft,NULL,&(SDL_Rect){bx+20,by+bh-fh-12,fw,fh});
    }
}

/* ======================================================================= *
 *  Mini Games  --  built-in, offline, no emulator / ROM / network.        *
 *  Add one: pick an id, write reset/key/step/render, add an mg_games[]     *
 *  row + an icon case in mg_icon(), and wire it into STATE_MINIGAME.       *
 *  Best score + total playtime persist to <data>/minigames.dat.           *
 * ======================================================================= */
#define MG_SNAKE     0
#define MG_PONG      1
#define MG_FLAP      2
#define MG_BREAKOUT  3
#define MG_TTT       4
#define MG_BLOXORZ   5
#define MG_DUCKDASH  6
#define MG_COUNT     7

typedef struct { const char *name; const char *tagline; const char *best_label; } MgInfo;
static const MgInfo mg_games[MG_COUNT] = {
    { "Snake",         "Eat, grow, don't bite yourself.",        "Best" },
    { "Pong",          "First to 7 beats the machine.",           "Wins" },
    { "Flapping Bird", "Tap A. Mind the pipes.",                  "Best" },
    { "Breakout",      "Clear every brick, keep the ball alive.", "Best" },
    { "Connect 4",     "Drop four in a row against the CPU.",      "Wins" },
    { "Block Roll",    "Ten stages of rolling block puzzles.",      "Levels" },
    { "Duck Dash",     "Line up the reticle and take the shot.",   "Best" },
};

static int mg_best[MG_COUNT] = { 0, 0, 0, 0, 0, 0, 0 };   // high score / win count (persisted)
static int mg_menu_sel = 0;                         // highlighted game on the picker
static int mg_cur = 0;                              // game currently being played

static const char *mg_data_path(void) {
    static char p[512];
    snprintf(p, sizeof p, "%s/minigames.dat", sn_data_root());
    return p;
}
static void minigames_save(void) {
    FILE *f = fopen(mg_data_path(), "w");
    if (!f) return;
    fprintf(f, "play_seconds=%ld\n", mg_play_seconds);
    for (int i = 0; i < MG_COUNT; i++) fprintf(f, "best%d=%d\n", i, mg_best[i]);
    fclose(f);
}
static void minigames_load(void) {
    FILE *f = fopen(mg_data_path(), "r");
    if (!f) return;
    char line[128];
    while (fgets(line, sizeof line, f)) {
        long l; int idx, v;
        if      (sscanf(line, "play_seconds=%ld", &l) == 1) mg_play_seconds = l >= 0 ? l : 0;
        else if (sscanf(line, "best%d=%d", &idx, &v) == 2 && idx >= 0 && idx < MG_COUNT) mg_best[idx] = v;
    }
    fclose(f);
    // Pre-1.1.8 stored Block Roll's fewest-moves record in this slot. Values
    // above the new ten-level range are an old-format score, not progress.
    if (mg_best[MG_BLOXORZ] < 0 || mg_best[MG_BLOXORZ] > 10) mg_best[MG_BLOXORZ] = 0;
}
static void mg_set_best(int game, int val) {
    if (game >= 0 && game < MG_COUNT && val > mg_best[game]) { mg_best[game] = val; minigames_save(); }
}

// Tiny procedural glyph per game, drawn in an s x s box at (x, y).
static void mg_icon(SDL_Renderer *ren, int id, int x, int y, int s, SDL_Color c) {
    SDL_SetRenderDrawColor(ren, c.r, c.g, c.b, 255);
    int q = s / 4; if (q < 3) q = 3;
    if (id == MG_SNAKE) {
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + q,     y + 2*q, q, q });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + 2*q,   y + 2*q, q, q });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + 2*q,   y + q,   q, q });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s - q - 2, y + 3*q, q - 1, q - 1 });
    } else if (id == MG_PONG) {
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + 2,     y + q,   3, 2*q });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s - 5, y + q,   3, 2*q });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s/2 - 2, y + s/2 - 2, 4, 4 });
    } else if (id == MG_FLAP) {
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + q,       y + s/2 - 3, 7, 7 });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s - 2*q, y,           q, q + 2 });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s - 2*q, y + s - q - 2, q, q + 2 });
    } else if (id == MG_BREAKOUT) {
        for (int i = 0; i < 3; i++)
            SDL_RenderFillRect(ren, &(SDL_Rect){ x + 2 + i*(q + 2), y + q, q, 4 });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s/2 - q/2, y + s - 5, q, 3 });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s/2 - 1,   y + s/2,   3, 3 });
    } else if (id == MG_TTT) {
        SDL_RenderDrawLine(ren, x + q,     y + 2,     x + q,     y + s - 2);
        SDL_RenderDrawLine(ren, x + s - q, y + 2,     x + s - q, y + s - 2);
        SDL_RenderDrawLine(ren, x + 2,     y + q,     x + s - 2, y + q);
        SDL_RenderDrawLine(ren, x + 2,     y + s - q, x + s - 2, y + s - q);
        SDL_RenderDrawLine(ren, x + 3,     y + 3,     x + q - 3, y + q - 3);
        SDL_RenderDrawLine(ren, x + q - 3, y + 3,     x + 3,     y + q - 3);
    } else if (id == MG_BLOXORZ) {
        SDL_RenderDrawRect(ren, &(SDL_Rect){ x + 2, y + s - q - 2, s - 4, q });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s/2 - q/2, y + q/2, q, s - q - 3 });
        SDL_RenderDrawRect(ren, &(SDL_Rect){ x + s/2 - q/2, y + q/2, q, s - q - 3 });
    } else { /* MG_DUCKDASH */
        SDL_RenderDrawLine(ren, x + 2, y + s/2, x + s - 2, y + s/2);
        SDL_RenderDrawLine(ren, x + s/2, y + 2, x + s/2, y + s - 2);
        SDL_RenderDrawRect(ren, &(SDL_Rect){ x + q, y + q, s - 2*q, s - 2*q });
        SDL_RenderFillRect(ren, &(SDL_Rect){ x + s/2 + 2, y + q - 2, q, q/2 + 2 });
    }
}

static Theme *mg_theme(void) {
    return &themes[(theme_idx >= 0 && theme_idx < THEME_COUNT) ? theme_idx : 0];
}
// shared: game name + exit hint across the top -- kept clear of the status bar
static void mg_chrome(SDL_Renderer *ren, const char *name) {
    Theme *th = mg_theme();
    SDL_Texture *nt = render_text(ren, font_small, name, th->accent2);
    int w, h; SDL_QueryTexture(nt, NULL, NULL, &w, &h);
    SDL_RenderCopy(ren, nt, NULL, &(SDL_Rect){ 30, 52, w, h });
    SDL_Texture *bk = render_text(ren, font_label, "B  Exit", g_ui_dim);
    int bw, bh; SDL_QueryTexture(bk, NULL, NULL, &bw, &bh);
    SDL_RenderCopy(ren, bk, NULL, &(SDL_Rect){ WIN_W - bw - 30, 56, bw, bh });
}

/* ----------------------------- Snake ----------------------------------- */
#define SNAKE_MAX 1400
static struct {
    int cell, cols, rows, ox, oy;
    int body[SNAKE_MAX][2];
    int len, dir, ndir;
    int fx, fy;
    int score, dead, started;
    Uint32 last;
    int step_ms;
} sk;

static void snake_food(void) {
    for (int tries = 0; tries < 600; tries++) {
        int x = rand() % sk.cols, y = rand() % sk.rows, ok = 1;
        for (int i = 0; i < sk.len; i++) if (sk.body[i][0] == x && sk.body[i][1] == y) { ok = 0; break; }
        if (ok) { sk.fx = x; sk.fy = y; return; }
    }
}
static void snake_reset(void) {
    sk.cell = 16;
    sk.cols = (WIN_W - 120) / sk.cell;
    sk.rows = (WIN_H - 188) / sk.cell;
    if (sk.cols > 40) sk.cols = 40;
    if (sk.rows > 22) sk.rows = 22;
    sk.ox = (WIN_W - sk.cols * sk.cell) / 2;
    sk.oy = 108 + ((WIN_H - 108 - 44) - sk.rows * sk.cell) / 2;
    if (sk.oy < 100) sk.oy = 100;
    sk.len = 4;
    for (int i = 0; i < sk.len; i++) { sk.body[i][0] = sk.cols/2 - i; sk.body[i][1] = sk.rows/2; }
    sk.dir = sk.ndir = 1;
    sk.score = 0; sk.dead = 0; sk.started = 0;
    sk.step_ms = 130;
    sk.last = SDL_GetTicks();
    snake_food();
}
static void snake_key(SDL_Keycode k) {
    if (sk.dead) { if (k == SDLK_RETURN) snake_reset(); return; }
    int is_dir = (k == SDLK_UP || k == SDLK_DOWN || k == SDLK_LEFT || k == SDLK_RIGHT);
    if      (k == SDLK_UP    && sk.dir != 2) sk.ndir = 0;
    else if (k == SDLK_RIGHT && sk.dir != 3) sk.ndir = 1;
    else if (k == SDLK_DOWN  && sk.dir != 0) sk.ndir = 2;
    else if (k == SDLK_LEFT  && sk.dir != 1) sk.ndir = 3;
    if (k == SDLK_RETURN || is_dir) sk.started = 1;
}
static void snake_step(void) {
    if (!sk.started || sk.dead) return;
    Uint32 now = SDL_GetTicks();
    if (now - sk.last < (Uint32)sk.step_ms) return;
    sk.last = now;
    sk.dir = sk.ndir;
    int hx = sk.body[0][0], hy = sk.body[0][1];
    if      (sk.dir == 0) hy--;
    else if (sk.dir == 1) hx++;
    else if (sk.dir == 2) hy++;
    else                  hx--;
    int hit = (hx < 0 || hy < 0 || hx >= sk.cols || hy >= sk.rows);
    for (int i = 0; !hit && i < sk.len - 1; i++)
        if (sk.body[i][0] == hx && sk.body[i][1] == hy) hit = 1;
    if (hit) {
        sk.dead = 1;
        mg_set_best(MG_SNAKE, sk.score);
        return;
    }
    int grow = (hx == sk.fx && hy == sk.fy);
    int n = sk.len + (grow ? 1 : 0);
    if (n > SNAKE_MAX) n = SNAKE_MAX;
    for (int i = n - 1; i > 0; i--) { sk.body[i][0] = sk.body[i-1][0]; sk.body[i][1] = sk.body[i-1][1]; }
    sk.body[0][0] = hx; sk.body[0][1] = hy;
    sk.len = n;
    if (grow) {
        sk.score++;
        if (sk.step_ms > 62) sk.step_ms -= 3;
        snake_food();
    }
}
static void snake_render(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    mg_chrome(ren, "SNAKE");
    char s[64]; snprintf(s, sizeof s, "Apples  %d       Best  %d", sk.score, mg_best[MG_SNAKE]);
    SDL_Texture *hud = render_text(ren, font_label, s, g_ui_text);
    int hw, hh; SDL_QueryTexture(hud, NULL, NULL, &hw, &hh);
    SDL_RenderCopy(ren, hud, NULL, &(SDL_Rect){ sk.ox, sk.oy - hh - 10, hw, hh });

    SDL_Rect bd = { sk.ox - 4, sk.oy - 4, sk.cols*sk.cell + 8, sk.rows*sk.cell + 8 };
    SDL_SetRenderDrawColor(ren, th->select_bg.r, th->select_bg.g, th->select_bg.b, 255);
    SDL_RenderFillRect(ren, &bd);
    SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
    SDL_RenderDrawRect(ren, &bd);

    SDL_SetRenderDrawColor(ren, th->accent3.r, th->accent3.g, th->accent3.b, 255);
    SDL_RenderFillRect(ren, &(SDL_Rect){ sk.ox + sk.fx*sk.cell + 2, sk.oy + sk.fy*sk.cell + 2, sk.cell - 4, sk.cell - 4 });

    for (int i = 0; i < sk.len; i++) {
        SDL_Color c = (i == 0) ? th->accent1 : th->text;
        SDL_SetRenderDrawColor(ren, c.r, c.g, c.b, i == 0 ? 255 : 205);
        SDL_RenderFillRect(ren, &(SDL_Rect){ sk.ox + sk.body[i][0]*sk.cell + 1, sk.oy + sk.body[i][1]*sk.cell + 1, sk.cell - 2, sk.cell - 2 });
    }

    const char *msg = !sk.started ? "Press A to start   -   D-pad to steer"
                    :  sk.dead     ? "Game Over   -   A retry   B exit"
                    :                NULL;
    if (msg) {
        SDL_Texture *m = render_text(ren, font_label, msg, th->accent2);
        int mw, mh; SDL_QueryTexture(m, NULL, NULL, &mw, &mh);
        SDL_Rect r = { WIN_W/2 - mw/2 - 12, sk.oy + sk.rows*sk.cell/2 - mh/2 - 6, mw + 24, mh + 12 };
        SDL_SetRenderDrawColor(ren, th->bg.r, th->bg.g, th->bg.b, 235);
        SDL_RenderFillRect(ren, &r);
        SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
        SDL_RenderDrawRect(ren, &r);
        SDL_RenderCopy(ren, m, NULL, &(SDL_Rect){ r.x + 12, r.y + 6, mw, mh });
    }
}

/* ------------------------------ Pong ---------------------------------- */
static struct {
    float bx, by, bvx, bvy;
    float you, cpu;
    int sy, sc, rally, over, winner, started;
    int top, bot, left, right, ph;
    float pw, br;
    Uint32 last;
} pg;

static void pong_serve(int to_you) {
    pg.bx = WIN_W / 2.0f;
    pg.by = (pg.top + pg.bot) / 2.0f;
    float sp = 4.6f;
    pg.bvx = to_you ? -sp : sp;
    pg.bvy = (((rand() % 200) / 100.0f) - 1.0f) * 3.2f;
    pg.rally = 0;
}
static void pong_reset(void) {
    pg.top = 104; pg.bot = WIN_H - 44;
    pg.left = 46; pg.right = WIN_W - 46;
    pg.ph = 46; pg.pw = 9; pg.br = 7;
    pg.you = pg.cpu = (pg.top + pg.bot) / 2.0f;
    pg.sy = pg.sc = 0; pg.over = 0; pg.winner = 0; pg.started = 0;
    pg.last = SDL_GetTicks();
    pong_serve(rand() & 1);
}
static void pong_key(SDL_Keycode k) {
    if (k == SDLK_RETURN) {
        if (pg.over) pong_reset();
        else pg.started = 1;
    }
}
static void pong_step(int mv) {                    // mv: -1 up, 0, +1 down (held)
    Uint32 now = SDL_GetTicks();
    Uint32 dtm = now - pg.last;
    pg.last = now;
    if (dtm > 64) dtm = 64;
    float t = dtm / 16.6667f;                      // ~1.0 per 60fps frame
    if (pg.over || !pg.started) return;

    float lo = pg.top + pg.ph / 2.0f, hi = pg.bot - pg.ph / 2.0f;
    pg.you += mv * 6.4f * t;
    if (pg.you < lo) pg.you = lo;
    if (pg.you > hi) pg.you = hi;

    float aim = pg.by + pg.bvy * 2.0f;
    float cs = 4.6f * t;
    if      (pg.cpu < aim - 7) pg.cpu += cs;
    else if (pg.cpu > aim + 7) pg.cpu -= cs;
    if (pg.cpu < lo) pg.cpu = lo;
    if (pg.cpu > hi) pg.cpu = hi;

    pg.bx += pg.bvx * t;
    pg.by += pg.bvy * t;
    if (pg.by < pg.top + pg.br)  { pg.by = pg.top + pg.br;  pg.bvy = -pg.bvy; }
    if (pg.by > pg.bot - pg.br)  { pg.by = pg.bot - pg.br;  pg.bvy = -pg.bvy; }

    if (pg.bvx < 0 && pg.bx - pg.br <= pg.left + pg.pw && pg.bx > pg.left - 6) {
        if (fabsf(pg.by - pg.you) <= pg.ph / 2.0f + pg.br) {
            pg.bx = pg.left + pg.pw + pg.br;
            pg.bvx = fabsf(pg.bvx) + 0.3f;
            pg.bvy += (pg.by - pg.you) * 0.13f;
            pg.rally++;
        }
    }
    if (pg.bvx > 0 && pg.bx + pg.br >= pg.right - pg.pw && pg.bx < pg.right + 6) {
        if (fabsf(pg.by - pg.cpu) <= pg.ph / 2.0f + pg.br) {
            pg.bx = pg.right - pg.pw - pg.br;
            pg.bvx = -(fabsf(pg.bvx) + 0.3f);
            pg.bvy += (pg.by - pg.cpu) * 0.13f;
            pg.rally++;
        }
    }
    if (pg.bvx >  9.5f) pg.bvx =  9.5f;
    if (pg.bvx < -9.5f) pg.bvx = -9.5f;

    if (pg.bx < pg.left - 18) { pg.sc++; pong_serve(0); }
    else if (pg.bx > pg.right + 18) { pg.sy++; pong_serve(1); }
    if (pg.sy >= 7 || pg.sc >= 7) {
        pg.over = 1;
        pg.winner = (pg.sy >= 7) ? 1 : 2;
        if (pg.winner == 1) mg_set_best(MG_PONG, mg_best[MG_PONG] + 1);   // count a win
    }
}
static void pong_render(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    mg_chrome(ren, "PONG");

    SDL_SetRenderDrawColor(ren, th->dim.r, th->dim.g, th->dim.b, 130);
    for (int y = pg.top; y < pg.bot; y += 22)
        SDL_RenderFillRect(ren, &(SDL_Rect){ WIN_W/2 - 1, y, 2, 12 });
    SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
    SDL_RenderDrawLine(ren, pg.left - 8, pg.top - 6, pg.right + 8, pg.top - 6);
    SDL_RenderDrawLine(ren, pg.left - 8, pg.bot + 6, pg.right + 8, pg.bot + 6);

    char sc[32]; snprintf(sc, sizeof sc, "%d      %d", pg.sy, pg.sc);
    SDL_Texture *st = render_text(ren, font_small, sc, g_ui_text);
    int sw, shh; SDL_QueryTexture(st, NULL, NULL, &sw, &shh);
    SDL_RenderCopy(ren, st, NULL, &(SDL_Rect){ WIN_W/2 - sw/2, pg.top - shh - 8, sw, shh });

    SDL_SetRenderDrawColor(ren, th->accent1.r, th->accent1.g, th->accent1.b, 255);
    SDL_RenderFillRect(ren, &(SDL_Rect){ pg.left, (int)(pg.you - pg.ph/2.0f), (int)pg.pw, pg.ph });
    SDL_SetRenderDrawColor(ren, th->text.r, th->text.g, th->text.b, 255);
    SDL_RenderFillRect(ren, &(SDL_Rect){ (int)(pg.right - pg.pw), (int)(pg.cpu - pg.ph/2.0f), (int)pg.pw, pg.ph });

    SDL_SetRenderDrawColor(ren, th->text.r, th->text.g, th->text.b, 255);
    SDL_RenderFillRect(ren, &(SDL_Rect){ (int)(pg.bx - pg.br), (int)(pg.by - pg.br), (int)(pg.br*2), (int)(pg.br*2) });

    const char *msg = !pg.started ? "Press A to serve   -   D-pad to move"
                    :  pg.over     ? (pg.winner == 1 ? "You win!  A play again   B exit"
                                                     : "CPU wins.  A play again   B exit")
                    :                NULL;
    if (msg) {
        SDL_Texture *m = render_text(ren, font_label, msg, th->accent2);
        int mw, mh; SDL_QueryTexture(m, NULL, NULL, &mw, &mh);
        SDL_Rect r = { WIN_W/2 - mw/2 - 12, (pg.top + pg.bot)/2 - mh/2 - 6, mw + 24, mh + 12 };
        SDL_SetRenderDrawColor(ren, th->bg.r, th->bg.g, th->bg.b, 235);
        SDL_RenderFillRect(ren, &r);
        SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
        SDL_RenderDrawRect(ren, &r);
        SDL_RenderCopy(ren, m, NULL, &(SDL_Rect){ r.x + 12, r.y + 6, mw, mh });
    }
}

/* -------------------------- Flapping Bird ---------------------------- */
#define FLAP_PIPES 3
static struct {
    int bx, top, bot, gap, pw, speed;
    float by, bvy;
    float px[FLAP_PIPES];
    int   pgc[FLAP_PIPES], ppass[FLAP_PIPES];
    int score, dead, started;
    Uint32 last;
} fb;

static void flap_newpipe(int i, float atx) {
    int room = fb.bot - fb.top - fb.gap;
    if (room < 24) room = 24;
    fb.px[i]   = atx;
    fb.pgc[i]  = fb.top + fb.gap / 2 + rand() % room;
    fb.ppass[i] = 0;
}
static void flap_reset(void) {
    fb.top = 98; fb.bot = WIN_H - 46;
    fb.bx  = WIN_W / 3;
    fb.by  = (fb.top + fb.bot) / 2.0f; fb.bvy = 0;
    fb.gap = 128; fb.pw = 46; fb.speed = 3;
    for (int i = 0; i < FLAP_PIPES; i++)
        flap_newpipe(i, WIN_W + 30 + i * ((WIN_W - 60) / FLAP_PIPES + 40));
    fb.score = 0; fb.dead = 0; fb.started = 0;
    fb.last = SDL_GetTicks();
}
static void flap_key(SDL_Keycode k) {
    if (k != SDLK_RETURN) return;
    if (fb.dead) { flap_reset(); return; }
    fb.started = 1;
    fb.bvy = -5.4f;
}
static void flap_step(void) {
    Uint32 now = SDL_GetTicks();
    Uint32 dt = now - fb.last; fb.last = now;
    if (dt > 64) dt = 64;
    float t = dt / 16.6667f;
    if (fb.dead || !fb.started) return;
    fb.bvy += 0.42f * t;
    if (fb.bvy > 8.5f) fb.bvy = 8.5f;
    fb.by  += fb.bvy * t;
    if (fb.by < fb.top + 6) { fb.by = fb.top + 6; fb.bvy = 0; }
    if (fb.by > fb.bot - 6) { fb.dead = 1; mg_set_best(MG_FLAP, fb.score); return; }
    for (int i = 0; i < FLAP_PIPES; i++) {
        fb.px[i] -= fb.speed * t;
        if (fb.px[i] + fb.pw < 0) {
            float mx = 0; for (int j = 0; j < FLAP_PIPES; j++) if (fb.px[j] > mx) mx = fb.px[j];
            flap_newpipe(i, mx + (WIN_W - 60) / FLAP_PIPES + 40);
        }
        if (!fb.ppass[i] && fb.px[i] + fb.pw < fb.bx) {
            fb.ppass[i] = 1; fb.score++;
            if ((fb.score % 6) == 0 && fb.speed < 6) fb.speed++;
        }
        if (fb.bx + 6 > fb.px[i] && fb.bx - 6 < fb.px[i] + fb.pw &&
            (fb.by - 6 < fb.pgc[i] - fb.gap / 2 || fb.by + 6 > fb.pgc[i] + fb.gap / 2)) {
            fb.dead = 1; mg_set_best(MG_FLAP, fb.score); return;
        }
    }
}
static void flap_render(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    mg_chrome(ren, "FLAPPING BIRD");
    SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
    SDL_RenderDrawLine(ren, 20, fb.top - 4, WIN_W - 20, fb.top - 4);
    SDL_RenderDrawLine(ren, 20, fb.bot + 4, WIN_W - 20, fb.bot + 4);
    SDL_SetRenderDrawColor(ren, th->accent1.r, th->accent1.g, th->accent1.b, 255);
    for (int i = 0; i < FLAP_PIPES; i++) {
        int px = (int)fb.px[i];
        SDL_RenderFillRect(ren, &(SDL_Rect){ px, fb.top, fb.pw, fb.pgc[i] - fb.gap/2 - fb.top });
        SDL_RenderFillRect(ren, &(SDL_Rect){ px, fb.pgc[i] + fb.gap/2, fb.pw, fb.bot - (fb.pgc[i] + fb.gap/2) });
    }
    SDL_SetRenderDrawColor(ren, th->text.r, th->text.g, th->text.b, 255);
    SDL_RenderFillRect(ren, &(SDL_Rect){ fb.bx - 6, (int)fb.by - 6, 12, 12 });
    char s[24]; snprintf(s, sizeof s, "%d", fb.score);
    SDL_Texture *st = render_text(ren, font_small, s, g_ui_text);
    int sw, sh; SDL_QueryTexture(st, NULL, NULL, &sw, &sh);
    SDL_RenderCopy(ren, st, NULL, &(SDL_Rect){ WIN_W/2 - sw/2, fb.top + 8, sw, sh });
    const char *msg = !fb.started ? "Press A to flap   -   Best  " : fb.dead ? "Game Over   -   A retry   B exit" : NULL;
    if (msg) {
        char line[64];
        if (!fb.started) snprintf(line, sizeof line, "Press A to flap      Best  %d", mg_best[MG_FLAP]);
        else             snprintf(line, sizeof line, "%s", msg);
        SDL_Texture *m = render_text(ren, font_label, line, th->accent2);
        int mw, mh; SDL_QueryTexture(m, NULL, NULL, &mw, &mh);
        SDL_Rect r = { WIN_W/2 - mw/2 - 12, (fb.top + fb.bot)/2 - mh/2 - 6, mw + 24, mh + 12 };
        SDL_SetRenderDrawColor(ren, th->bg.r, th->bg.g, th->bg.b, 235); SDL_RenderFillRect(ren, &r);
        SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255); SDL_RenderDrawRect(ren, &r);
        SDL_RenderCopy(ren, m, NULL, &(SDL_Rect){ r.x + 12, r.y + 6, mw, mh });
    }
}

/* ----------------------------- Breakout ----------------------------- */
#define BRK_COLS 9
#define BRK_ROWS 5
static struct {
    int top, bot, left, right, pw, ph, bw, bh, bx0, by0;
    float px, bx, by, bvx, bvy;
    int brick[BRK_ROWS][BRK_COLS];
    int lives, score, cleared, level, level_bricks, over, won, started;
    Uint32 last;
} bo;

static void brk_fill_level(void) {
    bo.cleared = 0; bo.level_bricks = 0;
    for (int r=0;r<BRK_ROWS;r++) for(int c=0;c<BRK_COLS;c++) {
        int on = bo.level <= 2 || ((r+c+bo.level)%3 != 0) || r==BRK_ROWS-1;
        bo.brick[r][c]=on; bo.level_bricks += on;
    }
    bo.pw = 70;
}

static void brk_reset(void) {
    bo.top = 100; bo.bot = WIN_H - 40;
    bo.left = 40; bo.right = WIN_W - 40;
    bo.pw = 70; bo.ph = 9;
    bo.bw = (bo.right - bo.left) / BRK_COLS; bo.bh = 16;
    bo.bx0 = bo.left; bo.by0 = bo.top + 8;
    bo.level = 1; brk_fill_level();
    bo.px = WIN_W / 2.0f;
    bo.bx = bo.px; bo.by = bo.bot - 24; bo.bvx = bo.bvy = 0;
    bo.lives = 3; bo.score = 0; bo.over = 0; bo.won = 0; bo.started = 0;
    bo.last = SDL_GetTicks();
}
static void brk_launch(void) {
    bo.bx = bo.px; bo.by = bo.bot - 26;
    bo.bvx = (rand() & 1) ? 3.0f : -3.0f;
    bo.bvy = -4.4f;
    bo.started = 1;
}
static void brk_key(SDL_Keycode k) {
    if (k != SDLK_RETURN) return;
    if (bo.over) { brk_reset(); return; }
    if (bo.bvx == 0 && bo.bvy == 0) brk_launch();
}
static void brk_step(int mvx) {
    Uint32 now = SDL_GetTicks();
    Uint32 dt = now - bo.last; bo.last = now;
    if (dt > 64) dt = 64;
    float t = dt / 16.6667f;
    float half = bo.pw / 2.0f;
    bo.px += mvx * 7.0f * t;
    if (bo.px < bo.left + half)  bo.px = bo.left + half;
    if (bo.px > bo.right - half) bo.px = bo.right - half;
    if (bo.over || (bo.bvx == 0 && bo.bvy == 0)) return;

    bo.bx += bo.bvx * t;
    bo.by += bo.bvy * t;
    if (bo.bx < bo.left + 5)  { bo.bx = bo.left + 5;  bo.bvx =  fabsf(bo.bvx); }
    if (bo.bx > bo.right - 5) { bo.bx = bo.right - 5; bo.bvx = -fabsf(bo.bvx); }
    if (bo.by < bo.top + 5)   { bo.by = bo.top + 5;   bo.bvy =  fabsf(bo.bvy); }

    if (bo.bvy > 0 && bo.by + 5 >= bo.bot - bo.ph && bo.by < bo.bot + 6 &&
        fabsf(bo.bx - bo.px) <= half + 5) {
        bo.by = bo.bot - bo.ph - 5;
        bo.bvy = -fabsf(bo.bvy);
        bo.bvx += (bo.bx - bo.px) * 0.09f;
        if (bo.bvx > 6.5f) bo.bvx = 6.5f;
        if (bo.bvx < -6.5f) bo.bvx = -6.5f;
    }
    int cc = (int)((bo.bx - bo.bx0) / bo.bw);
    int rr = (int)((bo.by - bo.by0) / bo.bh);
    if (cc >= 0 && cc < BRK_COLS && rr >= 0 && rr < BRK_ROWS && bo.brick[rr][cc]) {
        bo.brick[rr][cc] = 0;
        bo.score += 10; bo.cleared++;
        bo.bvy = -bo.bvy;
        if ((bo.cleared % 12) == 0) bo.pw = 110; // classic-style wide-paddle power-up
        if ((bo.cleared % 10) == 0) { bo.bvx *= 1.05f; bo.bvy *= 1.05f; }
        if (bo.cleared >= bo.level_bricks) {
            if (bo.level >= 10) { bo.over = 1; bo.won = 1; mg_set_best(MG_BREAKOUT, bo.score); }
            else { bo.level++; brk_fill_level(); bo.bvx = bo.bvy = 0; bo.bx = bo.px; bo.by = bo.bot - 26; }
        }
    }
    if (bo.by > bo.bot + 16) {
        bo.lives--;
        if (bo.lives <= 0) { bo.over = 1; bo.won = 0; mg_set_best(MG_BREAKOUT, bo.score); }
        else { bo.bvx = bo.bvy = 0; bo.by = bo.bot - 26; bo.bx = bo.px; }
    }
}
static void brk_render(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    mg_chrome(ren, "BREAKOUT");
    char hud[80]; snprintf(hud, sizeof hud, "Level %d/10   Score %d   Lives %d   Best %d", bo.level, bo.score, bo.lives, mg_best[MG_BREAKOUT]);
    SDL_Texture *ht = render_text(ren, font_label, hud, g_ui_text);
    int hw, hh; SDL_QueryTexture(ht, NULL, NULL, &hw, &hh);
    SDL_RenderCopy(ren, ht, NULL, &(SDL_Rect){ bo.left, bo.top - hh - 8, hw, hh });

    SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
    SDL_RenderDrawRect(ren, &(SDL_Rect){ bo.left - 4, bo.top - 4, bo.right - bo.left + 8, bo.bot - bo.top + 8 });
    for (int r = 0; r < BRK_ROWS; r++) for (int c = 0; c < BRK_COLS; c++) {
        if (!bo.brick[r][c]) continue;
        SDL_Color bc = (r < 2) ? th->accent2 : (r < 4) ? th->accent1 : th->accent3;
        SDL_SetRenderDrawColor(ren, bc.r, bc.g, bc.b, 255);
        SDL_RenderFillRect(ren, &(SDL_Rect){ bo.bx0 + c*bo.bw + 1, bo.by0 + r*bo.bh + 1, bo.bw - 3, bo.bh - 3 });
    }
    SDL_SetRenderDrawColor(ren, th->text.r, th->text.g, th->text.b, 255);
    SDL_RenderFillRect(ren, &(SDL_Rect){ (int)(bo.px - bo.pw/2.0f), bo.bot - bo.ph, bo.pw, bo.ph });
    SDL_RenderFillRect(ren, &(SDL_Rect){ (int)bo.bx - 5, (int)bo.by - 5, 10, 10 });

    const char *msg = bo.over ? (bo.won ? "You cleared it!  A play again   B exit"
                                        : "Game Over   -   A play again   B exit")
                    : (bo.bvx == 0 && bo.bvy == 0) ? "Press A to launch   -   D-pad to move"
                    : NULL;
    if (msg) {
        SDL_Texture *m = render_text(ren, font_label, msg, th->accent2);
        int mw, mh; SDL_QueryTexture(m, NULL, NULL, &mw, &mh);
        SDL_Rect r = { WIN_W/2 - mw/2 - 12, (bo.top + bo.bot)/2 - mh/2 - 6, mw + 24, mh + 12 };
        SDL_SetRenderDrawColor(ren, th->bg.r, th->bg.g, th->bg.b, 235); SDL_RenderFillRect(ren, &r);
        SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255); SDL_RenderDrawRect(ren, &r);
        SDL_RenderCopy(ren, m, NULL, &(SDL_Rect){ r.x + 12, r.y + 6, mw, mh });
    }
}

/* ------------------------------ Connect 4 --------------------------- */
#define C4_COLS 7
#define C4_ROWS 6
static struct { int cell[C4_ROWS*C4_COLS], cur, turn, over, winner; Uint32 cpu_at; } tt;

static int ttt_result(const int *c) {
    for (int r=0;r<C4_ROWS;r++) for (int x=0;x<C4_COLS;x++) {
        int who=c[r*C4_COLS+x]; if (!who) continue;
        const int d[4][2]={{1,0},{0,1},{1,1},{1,-1}};
        for (int k=0;k<4;k++) { int ok=1; for(int n=1;n<4;n++){int xx=x+d[k][0]*n,yy=r+d[k][1]*n; if(xx<0||xx>=C4_COLS||yy<0||yy>=C4_ROWS||c[yy*C4_COLS+xx]!=who){ok=0;break;}} if(ok)return who; }
    }
    for (int i=0;i<C4_ROWS*C4_COLS;i++) if(!c[i]) return 0;
    return 3;
}
static int c4_drop(int *c, int col, int who) {
    if (col<0||col>=C4_COLS) return -1;
    for(int r=C4_ROWS-1;r>=0;r--) if(!c[r*C4_COLS+col]) { c[r*C4_COLS+col]=who; return r; }
    return -1;
}
static int c4_tactical(int who) {
    for(int col=0;col<C4_COLS;col++){int tmp[C4_ROWS*C4_COLS];memcpy(tmp,tt.cell,sizeof tmp);if(c4_drop(tmp,col,who)>=0&&ttt_result(tmp)==who)return col;}
    return -1;
}
static void ttt_reset(void) {
    memset(tt.cell,0,sizeof tt.cell); tt.cur=3; tt.turn=1; tt.over=0; tt.winner=0; tt.cpu_at=0;
}
static void ttt_cpu(void) {
    int m=c4_tactical(2);
    // Block most obvious wins, but deliberately miss sometimes so every match
    // is not a perfect draw/loss against a tiny handheld CPU.
    if(m<0 && (rand()%100)<72) m=c4_tactical(1);
    if(m<0){int choices[C4_COLS],n=0;for(int c=0;c<C4_COLS;c++)if(!tt.cell[c])choices[n++]=c;if(n)m=choices[rand()%n];}
    if(m>=0)c4_drop(tt.cell,m,2);
    tt.turn=1; tt.winner=ttt_result(tt.cell); if(tt.winner)tt.over=1;
}
static void ttt_key(SDL_Keycode k) {
    if (tt.over) { if (k == SDLK_RETURN) ttt_reset(); return; }
    if (tt.turn != 1) return;
    if      (k == SDLK_LEFT)  tt.cur=(tt.cur+C4_COLS-1)%C4_COLS;
    else if (k == SDLK_RIGHT) tt.cur=(tt.cur+1)%C4_COLS;
    else if (k == SDLK_RETURN) {
        if (c4_drop(tt.cell,tt.cur,1)>=0) {
            tt.winner = ttt_result(tt.cell);
            if (tt.winner) { tt.over = 1; if (tt.winner == 1) mg_set_best(MG_TTT, mg_best[MG_TTT] + 1); }
            else { tt.turn = 2; tt.cpu_at = SDL_GetTicks() + 380; }
        }
    }
}
static void ttt_step(void) {
    if (!tt.over && tt.turn == 2 && SDL_GetTicks() >= tt.cpu_at) ttt_cpu();
}
static void ttt_render(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    mg_chrome(ren, "CONNECT 4");
    int gs = 48, bx = WIN_W/2 - gs*C4_COLS/2, by = 112;
    SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
    SDL_RenderDrawRect(ren,&(SDL_Rect){bx-3,by-3,gs*C4_COLS+6,gs*C4_ROWS+6});
    for (int i = 0; i < C4_ROWS*C4_COLS; i++) {
        int cx = bx + (i % C4_COLS) * gs, cy = by + (i / C4_COLS) * gs;
        if ((i%C4_COLS) == tt.cur && !tt.over && tt.turn == 1) {
            SDL_SetRenderDrawColor(ren, th->select_bg.r, th->select_bg.g, th->select_bg.b, 255);
            SDL_RenderFillRect(ren, &(SDL_Rect){ cx + 2, cy + 2, gs - 4, gs - 4 });
        }
        SDL_Color dc=tt.cell[i]==1?th->accent1:tt.cell[i]==2?th->accent3:th->bg;
        SDL_SetRenderDrawColor(ren,dc.r,dc.g,dc.b,255);
        fill_rounded(ren,(SDL_Rect){cx+8,cy+8,gs-16,gs-16},(gs-16)/2,dc.r,dc.g,dc.b,255);
    }
    const char *msg = tt.over ? (tt.winner == 1 ? "You win!   A play again   B exit"
                              :  tt.winner == 2 ? "CPU wins.   A play again   B exit"
                              :                   "Draw.   A play again   B exit")
                    : (tt.turn == 1 ? "Your move   -   Left / Right + A" : "CPU thinking...");
    SDL_Texture *m = render_text(ren, font_label, msg, th->accent2);
    int mw, mh; SDL_QueryTexture(m, NULL, NULL, &mw, &mh);
    SDL_RenderCopy(ren, m, NULL, &(SDL_Rect){ WIN_W/2 - mw/2, by + gs*C4_ROWS + 14, mw, mh });
}

/* ------------------------------ Block Roll -------------------------- */
#define BLK_W 11
#define BLK_H 8
#define BLK_LEVEL_COUNT 10
typedef struct {
    const char *row[BLK_H];
    int sx, sy, gx, gy;
} BlockLevel;

// Ten compact, independently solvable boards. They grow from a short tutorial
// route into offset platforms and carefully placed holes while remaining clear
// on the H700's 480px-tall screen.
static const BlockLevel blk_levels[BLK_LEVEL_COUNT] = {
    {{"...........",".#########.",".###.#####.",".#########.",".#####.###.",".#########.",".#########.","..........."}, 1,3, 7,3},
    {{"...........",".#######...",".#######...",".#######...",".#######...",".#######...","...........","..........."}, 1,1, 6,5},
    {{"...........","...#######.","...#######.",".#########.",".#########.",".######....",".######....","..........."}, 3,1, 1,6},
    {{"...........","..#######..","..#######..","..###.###..","..#######..","..#######..","..#######..","..........."}, 2,1, 8,6},
    {{"...........","..######...",".#########.",".#########.",".###.#####.",".#########.","....######.","..........."}, 2,1, 9,6},
    {{"...........",".#######...",".#######...",".#####.....",".#########.",".#########.",".#########.","..........."}, 1,1, 9,6},
    {{"...........",".#########.",".###.#####.",".###.#####.",".#####.###.",".#####.###.",".#########.","..........."}, 1,1, 9,6},
    {{"...........",".#########.",".##.######.",".#########.",".######.##.",".#########.",".#########.","..........."}, 1,6, 9,1},
    {{"...........",".#########.",".###.#####.",".#########.",".##.###.##.",".#########.",".#########.","..........."}, 1,1, 9,6},
    {{"...........",".#########.",".#########.",".##...####.",".#########.",".#########.",".#########.","..........."}, 1,1, 9,6},
};
static int blk_level = 0;
static struct { int x, y, orient, moves, won, failed; } br;

static int block_cell_ok(int x, int y) {
    return x >= 0 && y >= 0 && x < BLK_W && y < BLK_H && blk_levels[blk_level].row[y][x] == '#';
}
static int block_pose_ok(int x, int y, int o) {
    if (!block_cell_ok(x, y)) return 0;
    if (o == 1) return block_cell_ok(x + 1, y);
    if (o == 2) return block_cell_ok(x, y + 1);
    return 1;
}
static void block_retry(void) {
    const BlockLevel *lv = &blk_levels[blk_level];
    br.x = lv->sx; br.y = lv->sy; br.orient = 0; br.moves = 0; br.won = 0; br.failed = 0;
}
static void block_reset(void) {
    // Resume at the first unfinished stage; completing all ten starts a fresh run.
    blk_level = (mg_best[MG_BLOXORZ] > 0 && mg_best[MG_BLOXORZ] < BLK_LEVEL_COUNT)
              ? mg_best[MG_BLOXORZ] : 0;
    block_retry();
}
static void block_key(SDL_Keycode k) {
    if (br.won) {
        if (k == SDLK_RETURN) { blk_level = (blk_level + 1) % BLK_LEVEL_COUNT; block_retry(); }
        return;
    }
    if (br.failed) { if (k == SDLK_RETURN) block_retry(); return; }
    if (k != SDLK_UP && k != SDLK_DOWN && k != SDLK_LEFT && k != SDLK_RIGHT) return;
    int nx = br.x, ny = br.y, no = br.orient;
    if (br.orient == 0) {
        if      (k == SDLK_LEFT)  { nx -= 2; no = 1; }
        else if (k == SDLK_RIGHT) { nx += 1; no = 1; }
        else if (k == SDLK_UP)    { ny -= 2; no = 2; }
        else                      { ny += 1; no = 2; }
    } else if (br.orient == 1) {
        if      (k == SDLK_LEFT)  { nx -= 1; no = 0; }
        else if (k == SDLK_RIGHT) { nx += 2; no = 0; }
        else if (k == SDLK_UP)    ny -= 1;
        else if (k == SDLK_DOWN)  ny += 1;
    } else {
        if      (k == SDLK_UP)    { ny -= 1; no = 0; }
        else if (k == SDLK_DOWN)  { ny += 2; no = 0; }
        else if (k == SDLK_LEFT)  nx -= 1;
        else if (k == SDLK_RIGHT) nx += 1;
    }
    br.moves++;
    if (!block_pose_ok(nx, ny, no)) { br.failed = 1; return; }
    br.x = nx; br.y = ny; br.orient = no;
    const BlockLevel *lv = &blk_levels[blk_level];
    if (br.orient == 0 && br.x == lv->gx && br.y == lv->gy) {
        br.won = 1;
        mg_set_best(MG_BLOXORZ, blk_level + 1);
    }
}
static void block_render(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    mg_chrome(ren, "BLOCK ROLL");
    int cell = 38, ox = WIN_W/2 - BLK_W*cell/2, oy = 102;
    for (int y = 0; y < BLK_H; y++) for (int x = 0; x < BLK_W; x++) {
        if (!block_cell_ok(x, y)) continue;
        const BlockLevel *lv = &blk_levels[blk_level];
        SDL_Color tc = (x == lv->gx && y == lv->gy) ? th->accent3 : th->select_bg;
        SDL_SetRenderDrawColor(ren, tc.r, tc.g, tc.b, 245);
        SDL_RenderFillRect(ren, &(SDL_Rect){ ox + x*cell + 2, oy + y*cell + 2, cell - 4, cell - 4 });
        SDL_SetRenderDrawColor(ren, th->dim.r, th->dim.g, th->dim.b, 180);
        SDL_RenderDrawRect(ren, &(SDL_Rect){ ox + x*cell + 2, oy + y*cell + 2, cell - 4, cell - 4 });
    }
    int bw = cell - 12, bh = cell - 12;
    if (br.orient == 1) bw = cell*2 - 12;
    if (br.orient == 2) bh = cell*2 - 12;
    SDL_Rect b = { ox + br.x*cell + 6, oy + br.y*cell + 6, bw, bh };
    SDL_SetRenderDrawColor(ren, th->accent1.r, th->accent1.g, th->accent1.b, 255);
    SDL_RenderFillRect(ren, &b);
    SDL_SetRenderDrawColor(ren, th->text.r, th->text.g, th->text.b, 255);
    SDL_RenderDrawRect(ren, &b);
    char hud[96];
    snprintf(hud, sizeof hud, "Level %d/%d    Moves %d    Cleared %d/%d",
             blk_level + 1, BLK_LEVEL_COUNT, br.moves, mg_best[MG_BLOXORZ], BLK_LEVEL_COUNT);
    SDL_Texture *ht = render_text(ren, font_label, hud, g_ui_text);
    int hw, hh; SDL_QueryTexture(ht, NULL, NULL, &hw, &hh);
    SDL_RenderCopy(ren, ht, NULL, &(SDL_Rect){ ox, WIN_H - hh - 42, hw, hh });
    const char *msg = br.won ? (blk_level + 1 < BLK_LEVEL_COUNT ? "Solved!   A next level   B exit" : "All 10 cleared!   A restart   B exit")
                    : br.failed ? "The block fell.   A retry   B exit"
                    : "D-pad: roll    Goal: stand on bright tile";
    SDL_Texture *mt = render_text_fit(ren, font_label, msg, th->accent2, WIN_W - 60);
    int mw, mh; SDL_QueryTexture(mt, NULL, NULL, &mw, &mh);
    SDL_RenderCopy(ren, mt, NULL, &(SDL_Rect){ WIN_W/2 - mw/2, WIN_H - mh - 14, mw, mh });
}

/* ------------------------------- Duck Dash -------------------------- */
static struct {
    float x, y, vx, vy;
    int rx, ry, score, shots, over, started;
    Uint32 last, ends;
} dd;

static void duck_spawn(void) {
    dd.x = (rand() & 1) ? 70.0f : (float)(WIN_W - 70);
    dd.y = 120.0f + (float)(rand() % (WIN_H - 260));
    float speed = 2.6f + dd.score * 0.16f; if (speed > 6.5f) speed = 6.5f;
    dd.vx = (dd.x < WIN_W/2) ? speed : -speed;
    dd.vy = ((rand() % 200) / 100.0f - 1.0f) * 1.8f;
}
static void duck_reset(void) {
    dd.rx = WIN_W/2; dd.ry = WIN_H/2;
    dd.score = 0; dd.shots = 18; dd.over = 0; dd.started = 0;
    dd.last = SDL_GetTicks(); dd.ends = 0; duck_spawn();
}
static void duck_key(SDL_Keycode k) {
    if (dd.over) { if (k == SDLK_RETURN) duck_reset(); return; }
    if (k == SDLK_UP) dd.ry -= 14;
    else if (k == SDLK_DOWN) dd.ry += 14;
    else if (k == SDLK_LEFT) dd.rx -= 14;
    else if (k == SDLK_RIGHT) dd.rx += 14;
    else if (k == SDLK_RETURN) {
        if (!dd.started) { dd.started = 1; dd.ends = SDL_GetTicks() + 30000; return; }
        dd.shots--;
        float dx = dd.x - dd.rx, dy = dd.y - dd.ry;
        if (dx*dx + dy*dy <= 30.0f*30.0f) { dd.score++; duck_spawn(); }
        if (dd.shots <= 0) { dd.over = 1; mg_set_best(MG_DUCKDASH, dd.score); }
    }
    if (dd.rx < 24) dd.rx = 24;
    if (dd.rx > WIN_W - 24) dd.rx = WIN_W - 24;
    if (dd.ry < 100) dd.ry = 100;
    if (dd.ry > WIN_H - 54) dd.ry = WIN_H - 54;
}
static void duck_step(void) {
    Uint32 now = SDL_GetTicks(), dt = now - dd.last; dd.last = now;
    if (dt > 64) dt = 64;
    if (!dd.started || dd.over) return;
    float t = dt / 16.6667f;
    dd.x += dd.vx * t; dd.y += dd.vy * t;
    if (dd.x < 26) { dd.x = 26; dd.vx = fabsf(dd.vx); }
    if (dd.x > WIN_W - 26) { dd.x = WIN_W - 26; dd.vx = -fabsf(dd.vx); }
    if (dd.y < 104) { dd.y = 104; dd.vy = fabsf(dd.vy); }
    if (dd.y > WIN_H - 72) { dd.y = WIN_H - 72; dd.vy = -fabsf(dd.vy); }
    if (now >= dd.ends) { dd.over = 1; mg_set_best(MG_DUCKDASH, dd.score); }
}
static void duck_render(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    mg_chrome(ren, "DUCK DASH");
    SDL_SetRenderDrawBlendMode(ren, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 35);
    SDL_RenderFillRect(ren, &(SDL_Rect){ 20, 94, WIN_W - 40, WIN_H - 144 });
    SDL_SetRenderDrawColor(ren, th->accent1.r, th->accent1.g, th->accent1.b, 180);
    for (int x = 22; x < WIN_W - 22; x += 13) {
        int h = 6 + (x * 7) % 20;
        SDL_RenderDrawLine(ren, x, WIN_H - 50, x + 3, WIN_H - 50 - h);
    }
    int x = (int)dd.x, y = (int)dd.y;
    SDL_SetRenderDrawColor(ren, th->accent3.r, th->accent3.g, th->accent3.b, 255);
    SDL_RenderFillRect(ren, &(SDL_Rect){ x - 18, y - 8, 34, 16 });
    SDL_RenderFillRect(ren, &(SDL_Rect){ x + 10, y - 15, 13, 13 });
    SDL_RenderDrawLine(ren, x - 12, y - 6, x - 25, y - 18);
    SDL_RenderDrawLine(ren, x - 10, y + 5, x - 24, y + 17);
    SDL_SetRenderDrawColor(ren, th->text.r, th->text.g, th->text.b, 255);
    SDL_RenderDrawLine(ren, dd.rx - 18, dd.ry, dd.rx + 18, dd.ry);
    SDL_RenderDrawLine(ren, dd.rx, dd.ry - 18, dd.rx, dd.ry + 18);
    for (int o = 16; o <= 18; o++) SDL_RenderDrawRect(ren, &(SDL_Rect){ dd.rx - o, dd.ry - o, o*2, o*2 });
    int secs = (!dd.started || dd.over) ? 30 : (dd.ends > SDL_GetTicks() ? (int)((dd.ends - SDL_GetTicks() + 999) / 1000) : 0);
    char hud[80]; snprintf(hud, sizeof hud, "Score %d    Shots %d    Time %ds    Best %d", dd.score, dd.shots, secs, mg_best[MG_DUCKDASH]);
    SDL_Texture *ht = render_text(ren, font_label, hud, g_ui_text);
    int hw, hh; SDL_QueryTexture(ht, NULL, NULL, &hw, &hh);
    SDL_RenderCopy(ren, ht, NULL, &(SDL_Rect){ 30, 82, hw, hh });
    if (!dd.started || dd.over) {
        const char *msg = dd.over ? "Round over   -   A play again   B exit"
                                  : "A starts   -   D-pad aims   -   A fires";
        SDL_Texture *mt = render_text(ren, font_label, msg, th->accent2);
        int mw, mh; SDL_QueryTexture(mt, NULL, NULL, &mw, &mh);
        SDL_Rect panel = { WIN_W/2 - mw/2 - 12, WIN_H/2 - mh/2 - 6, mw + 24, mh + 12 };
        SDL_SetRenderDrawColor(ren, th->bg.r, th->bg.g, th->bg.b, 235); SDL_RenderFillRect(ren, &panel);
        SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255); SDL_RenderDrawRect(ren, &panel);
        SDL_RenderCopy(ren, mt, NULL, &(SDL_Rect){ panel.x + 12, panel.y + 6, mw, mh });
    }
}

/* -------------------------- Mini-games picker ----------------------- */
static void mg_render_menu(SDL_Renderer *ren) {
    Theme *th = mg_theme();
    draw_dock_logo(ren, font_small);

    SDL_Texture *title = render_text(ren, font_small, "MINI GAMES", th->accent2);
    int tw, tht; SDL_QueryTexture(title, NULL, NULL, &tw, &tht);
    SDL_RenderCopy(ren, title, NULL, &(SDL_Rect){ 40, 54, tw, tht });

    int lx = 34, rx = WIN_W - 34;
    int top = 100, bot = WIN_H - 52;
    const int visible = 5;
    int first = mg_menu_sel - visible + 1;
    if (first < 0) first = 0;
    if (first > MG_COUNT - visible) first = MG_COUNT - visible;
    if (first < 0) first = 0;
    int shown = MG_COUNT < visible ? MG_COUNT : visible;
    int rowh = (bot - top) / shown;
    if (rowh > 74) rowh = 74;
    int icon = rowh - 22; if (icon > 46) icon = 46;

    for (int i = first; i < MG_COUNT && i < first + visible; i++) {
        int sel = (i == mg_menu_sel);
        SDL_Rect rb = { lx, top + (i - first) * rowh, rx - lx, rowh - 8 };
        SDL_SetRenderDrawColor(ren, th->select_bg.r, th->select_bg.g, th->select_bg.b, sel ? 255 : 80);
        SDL_RenderFillRect(ren, &rb);
        if (sel) {
            for (int b = 0; b < 2; b++) {
                SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 255);
                SDL_RenderDrawRect(ren, &(SDL_Rect){ rb.x - b, rb.y - b, rb.w + 2*b, rb.h + 2*b });
            }
        }
        // icon box
        SDL_Rect ib = { rb.x + 12, rb.y + rb.h/2 - icon/2, icon, icon };
        SDL_SetRenderDrawColor(ren, th->bg.r, th->bg.g, th->bg.b, 255);
        SDL_RenderFillRect(ren, &ib);
        SDL_SetRenderDrawColor(ren, th->accent2.r, th->accent2.g, th->accent2.b, 200);
        SDL_RenderDrawRect(ren, &ib);
        mg_icon(ren, i, ib.x + 4, ib.y + 4, icon - 8, sel ? th->accent2 : g_ui_text);

        int tx = ib.x + icon + 16;
        int tmaxw = rb.w - (tx - rb.x) - 96;   // leave room for the "Best N" column
        TTF_Font *tagf = font_fixed ? font_fixed : font_label;
        SDL_Texture *nm = render_text(ren, font_label, mg_games[i].name, sel ? g_ui_text : g_ui_dim);
        int nw, nh; SDL_QueryTexture(nm, NULL, NULL, &nw, &nh);
        SDL_Texture *tg = render_text_fit(ren, tagf, mg_games[i].tagline, g_ui_dim, tmaxw);
        int tgw, tgh; SDL_QueryTexture(tg, NULL, NULL, &tgw, &tgh);
        int blk = nh + 4 + tgh;
        int ty = rb.y + rb.h/2 - blk/2;
        SDL_RenderCopy(ren, nm, NULL, &(SDL_Rect){ tx, ty, nw, nh });
        SDL_RenderCopy(ren, tg, NULL, &(SDL_Rect){ tx, ty + nh + 4, tgw, tgh });

        char b[24]; snprintf(b, sizeof b, "%s %d", mg_games[i].best_label, mg_best[i]);
        SDL_Texture *bt = render_text(ren, font_label, b, th->accent2);
        int bw, bh; SDL_QueryTexture(bt, NULL, NULL, &bw, &bh);
        SDL_RenderCopy(ren, bt, NULL, &(SDL_Rect){ rb.x + rb.w - bw - 14, rb.y + rb.h/2 - bh/2, bw, bh });
    }

    char footer[96];
    snprintf(footer, sizeof footer, "A  Play     B  Back     %d-%d of %d",
             first + 1, (first + visible < MG_COUNT) ? first + visible : MG_COUNT, MG_COUNT);
    SDL_Texture *ft = render_text(ren, font_label, footer, g_ui_dim);
    int fw, fh; SDL_QueryTexture(ft, NULL, NULL, &fw, &fh);
    SDL_RenderCopy(ren, ft, NULL, &(SDL_Rect){ 34, WIN_H - fh - 14, fw, fh });
}

// --- promo screenshot tour (dev only) ------------------------------------
// `./snapos_ui --promo [--promo-dir DIR]` walks the UI (themes, views, book,
// library, minigames, settings), saving a PNG per stop, then exits.
static int  promo_mode = 0;
static int  promo_start = 0;
static char promo_dir[512] = "";
static void save_screenshot(SDL_Renderer *ren, const char *path) {
    int w = 640, h = 480; SDL_GetRendererOutputSize(ren, &w, &h);
    SDL_Surface *s = SDL_CreateRGBSurfaceWithFormat(0, w, h, 32, SDL_PIXELFORMAT_ARGB8888);
    if (!s) return;
    if (SDL_RenderReadPixels(ren, NULL, SDL_PIXELFORMAT_ARGB8888, s->pixels, s->pitch) == 0) {
        if (IMG_SavePNG(s, path) != 0)
            fprintf(stderr, "promo: PNG save failed for %s: %s\n", path, IMG_GetError());
    } else fprintf(stderr, "promo: readback failed for %s: %s\n", path, SDL_GetError());
    SDL_FreeSurface(s);
}

// Promo runs must be useful offline and must never depend on the developer's
// cached station list. These clearly generic sample stations exercise the real
// radio UI without starting playback or making a network request.
